// Zusammenfassung Fertigungstechnik – eigene Formulierungen, nach den Prüfungsthemen der HQ-Prüfung
(window.TEXTBAND=window.TEXTBAND||{}).FT={
 title:'Fertigungstechnik',
 src:'Eigene Zusammenfassung nach den Prüfungsthemen der HQ-Prüfung Industriemeister Metall',
 intro:'Fertigungstechnik ist in der Prüfung ein Rechen- und Entscheidungsfach: Schnittwerte, Hauptnutzungszeit, Schnittleistung, Verfahrenswahl (spanend, thermisch, additiv, Fügen), Wärmebehandlung, Kühlschmierung, CNC und Roboter. Je Kapitel stehen die Formeln mit Einheiten, ein durchgerechnetes Beispiel und die typische Prüfungsfalle.',
 ch:[
  {t:'Fertigungsverfahren nach DIN 8580',h:'Sechs Hauptgruppen und ihre Merkmale',b:[
    {p:'DIN 8580 ordnet alle Fertigungsverfahren nach der Art, wie der Zusammenhalt des Werkstücks geschaffen, verändert oder vermindert wird. In der Prüfung muss ein Verfahren oft nur der richtigen Hauptgruppe zugeordnet und begründet werden.'},
    {tab:[['Nr.','Hauptgruppe','Zusammenhalt','Beispiele'],['1','Urformen','wird geschaffen','Gießen, Sintern, Pulverbettverfahren (SLS/SLM), Spritzgießen'],['2','Umformen','wird beibehalten','Schmieden, Gesenkschmieden, Tiefziehen, Biegen, Walzen'],['3','Trennen','wird vermindert','Drehen, Fräsen, Bohren, Schleifen, Scherschneiden, Brennschneiden, Laserschneiden'],['4','Fügen','wird vermehrt','Schweißen, Löten, Kleben, Schrauben, Nieten'],['5','Beschichten','wird vermehrt (Schicht)','Lackieren, Verzinken, Plasmaspritzen, Galvanik'],['6','Stoffeigenschaft ändern','Stoffeigenschaft ändert sich','Härten, Anlassen, Nitrieren, Glühen, Randschichthärten']]},
    {merke:'Merkhilfe für die Reihenfolge: Ur – Um – Trenn – Füg – Beschicht – Stoff ändern (1 bis 6).'},
    {p:'Additive Fertigung (3D-Druck im Pulverbett) gehört nach DIN 8580 zum Urformen: Aus formlosem Stoff (Pulver) entsteht Schicht für Schicht ein fester Körper. Ein anschließendes Zerspanen der Funktionsflächen ist dagegen Trennen.'},
    {ul:['Gesenkschmieden: Umformen (Massivumformen), Werkstück erhält die Form des Gesenks','Plasmanitrieren: Stoffeigenschaft ändern (Randschicht wird durch Stickstoff hart)','Sintern: Urformen aus Pulver mit anschließender Wärmebehandlung unterhalb der Schmelztemperatur','Randschichthärten: Stoffeigenschaft ändern; Kern bleibt zäh, Rand wird hart']},
    {falle:'Brennschneiden und Laserschneiden sind Trennen (thermisches Abtragen), nicht Umformen. Schweißen ist Fügen, auch wenn dabei Werkstoff aufgeschmolzen wird.'}]},

  {t:'Zerspanung: Schnittgrößen und Grundformeln',h:'Schnittgeschwindigkeit, Drehzahl, Vorschub, Spanungsquerschnitt',b:[
    {p:'Alle Zerspanverfahren arbeiten mit denselben Grundgrößen. Die Schnittgeschwindigkeit vc legt der Werkzeughersteller nach Werkstoff und Schneidstoff fest; Drehzahl und Vorschubgeschwindigkeit werden daraus berechnet.'},
    {fx:{n:'Schnittgeschwindigkeit und Drehzahl',tex:'v_c = \\pi \\cdot d \\cdot n \\qquad n = \\frac{v_c \\cdot 1000}{\\pi \\cdot d}',leg:[['v_c','Schnittgeschwindigkeit in m/min'],['d','Durchmesser von Werkstück (Drehen) bzw. Werkzeug (Fräsen, Bohren) in mm'],['n','Drehzahl in min⁻¹']],e:'Der Faktor 1000 rechnet mm in m um. Beim Drehen ist d der größte Durchmesser an der Schnittstelle.'}},
    {fx:{n:'Vorschubgeschwindigkeit',tex:'v_f = f \\cdot n',leg:[['v_f','Vorschubgeschwindigkeit in mm/min'],['f','Vorschub je Umdrehung in mm'],['n','Drehzahl in min⁻¹']]}},
    {fx:{n:'Spanungsquerschnitt',tex:'A = a_p \\cdot f = b \\cdot h \\qquad h = f \\cdot \\sin\\kappa \\qquad b = \\frac{a_p}{\\sin\\kappa}',leg:[['A','Spanungsquerschnitt in mm²'],['a_p','Schnitttiefe in mm'],['f','Vorschub in mm'],['b','Spanungsbreite in mm'],['h','Spanungsdicke in mm'],['\\kappa','Einstellwinkel der Schneide']],e:'Bei κ = 90° ist h = f und b = a_p.'}},
    {fx:{n:'Zeitspanvolumen',tex:'Q = a_p \\cdot f \\cdot v_c',leg:[['Q','Zeitspanvolumen in cm³/min (a_p, f in mm; v_c in m/min)'],['a_p','Schnitttiefe in mm'],['f','Vorschub in mm'],['v_c','Schnittgeschwindigkeit in m/min']],e:'Das Zeitspanvolumen zeigt, wie viel Werkstoff pro Minute abgetragen wird.'}},
    {fx:{n:'Schnittkraft nach Kienzle',tex:'F_c = A \\cdot k_c \\qquad k_c = \\frac{k_{c1.1}}{h^{m_c}}',leg:[['F_c','Schnittkraft in N'],['A','Spanungsquerschnitt in mm²'],['k_c','spezifische Schnittkraft in N/mm²'],['k_{c1.1}','spezifische Schnittkraft bei h = 1 mm und b = 1 mm (Tabellenwert)'],['h','Spanungsdicke in mm'],['m_c','Anstiegswert (Tabellenwert, 0,15 bis 0,35)']],e:'Je dünner der Span, desto größer die spezifische Schnittkraft: kc steigt, wenn h kleiner wird.'}},
    {fx:{n:'Schnittleistung und Antriebsleistung',tex:'P_c = \\frac{F_c \\cdot v_c}{60\\,000} \\qquad P_\\text{Motor} = \\frac{P_c}{\\eta}',leg:[['P_c','Schnittleistung in kW'],['F_c','Schnittkraft in N'],['v_c','Schnittgeschwindigkeit in m/min'],['\\eta','Wirkungsgrad der Maschine (meist 0,7 bis 0,9)']],e:'60 000 = 60 s/min · 1000 W/kW. Bohren und Fräsen: Kraft je Schneide mal Anzahl der im Eingriff befindlichen Schneiden.'}},
    {bsp:{t:'Beispiel: Antriebsleistung beim Längsdrehen',b:['Gegeben: d = 60 mm, vc = 180 m/min, a_p = 3 mm, f = 0,25 mm, κ = 90°, kc1.1 = 1800 N/mm², mc = 0,25, η = 0,8','Drehzahl: n = 180 · 1000 / (π · 60) = 955 min⁻¹','Spanungsdicke: h = f · sin 90° = 0,25 mm; A = 3 · 0,25 = 0,75 mm²','kc = 1800 / 0,25^0,25 = 1800 / 0,7071 = 2546 N/mm²','Schnittkraft: Fc = 0,75 · 2546 = 1909 N','Schnittleistung: Pc = 1909 · 180 / 60 000 = 5,73 kW','Motorleistung: P = 5,73 / 0,8 = 7,16 kW']}},
    {falle:'Bei Kienzle h und b nicht verwechseln: kc hängt von der Spanungsdicke h ab, nicht vom Vorschub f. Erst bei κ = 90° sind beide gleich. Und die Leistung durch den Wirkungsgrad teilen, nicht damit multiplizieren.'}]},

  {t:'Drehen',h:'Hauptnutzungszeit und typische Aufgaben',b:[
    {p:'Beim Längsdrehen bewegt sich das Werkzeug parallel zur Drehachse. Die Hauptnutzungszeit th ist die reine Zeit, in der das Werkzeug zerspant. Sie hängt vom Vorschubweg L, der Anzahl der Schnitte i und der Vorschubgeschwindigkeit ab.'},
    {fx:{n:'Hauptnutzungszeit Längsdrehen',tex:'t_h = \\frac{L \\cdot i}{n \\cdot f} \\qquad L = l + l_a + l_u',leg:[['t_h','Hauptnutzungszeit in min'],['L','Vorschubweg in mm'],['l','Länge der Bearbeitungsstelle in mm'],['l_a','Anlaufweg in mm'],['l_u','Überlaufweg in mm'],['i','Anzahl der Schnitte'],['n','Drehzahl in min⁻¹'],['f','Vorschub in mm']],e:'Anzahl der Schnitte: i = Gesamtzugabe : Schnitttiefe, immer aufrunden.'}},
    {fx:{n:'Plandrehen',tex:'t_h = \\frac{d/2 + l_a + l_u}{n \\cdot f}',leg:[['d','Durchmesser des Werkstücks in mm'],['n','Drehzahl in min⁻¹ (bei konstanter Schnittgeschwindigkeit ändert sie sich zur Mitte hin)']],e:'Bei Plandrehen mit konstanter Drehzahl wird mit dem größten Durchmesser gerechnet.'}},
    {bsp:{t:'Beispiel: Hauptnutzungszeit',b:['Welle Ø 60 mm, Länge 120 mm, Anlauf 2 mm, Überlauf 1 mm, 2 Schnitte, n = 955 min⁻¹, f = 0,25 mm','Vorschubweg: L = 120 + 2 + 1 = 123 mm','Hauptnutzungszeit: th = 123 · 2 / (955 · 0,25) = 246 / 238,75 = 1,03 min']}},
    {ul:['Schruppen: große Schnitttiefe, großer Vorschub, kleinere Schnittgeschwindigkeit','Schlichten: kleine Schnitttiefe, kleiner Vorschub, hohe Schnittgeschwindigkeit, bessere Oberfläche','Eckenradius r: bestimmt die theoretische Rautiefe – Rz ≈ f² / (8 · r), zugleich Grenze für den Vorschub','Spanbrechung (Spanform, Spanleitstufe, Spanbrecher) verhindert Wirrspäne und Bedienerrisiko']},
    {fx:{n:'Theoretische Rautiefe beim Drehen',tex:'R_z \\approx \\frac{f^{2}}{8 \\cdot r} \\cdot 1000',leg:[['R_z','gemittelte Rautiefe in µm'],['f','Vorschub in mm'],['r','Eckenradius der Wendeschneidplatte in mm']],e:'Der Faktor 1000 wandelt mm in µm um. Halber Vorschub ergibt ein Viertel der Rautiefe; größerer Eckenradius verbessert die Oberfläche.'}},
    {falle:'Rz nach der Formel immer in µm angeben und nicht mit mm mischen. Soll die Rautiefe eingehalten werden, ist der Vorschub zu begrenzen: f ≤ √(8 · r · Rz). Mit dem Vorschubgrenzwert ist dann die Zeitberechnung durchzuführen.'}]},

  {t:'Fräsen',h:'Planfräsen, Vorschub je Zahn, Hauptnutzungszeit und Antriebsleistung',b:[
    {p:'Beim Fräsen dreht das Werkzeug mit mehreren Schneiden (z Zähne), das Werkstück wird vorgeschoben. Maßgeblich ist der Vorschub je Zahn fz; er legt die Spanungsdicke und die Oberflächengüte fest.'},
    {fx:{n:'Vorschubgeschwindigkeit beim Fräsen',tex:'v_f = f_z \\cdot z \\cdot n',leg:[['v_f','Vorschubgeschwindigkeit in mm/min'],['f_z','Vorschub je Zahn in mm'],['z','Zähnezahl des Fräsers'],['n','Drehzahl in min⁻¹']]}},
    {fx:{n:'Hauptnutzungszeit Planfräsen',tex:'t_h = \\frac{L \\cdot i}{v_f} \\qquad L = l + l_a + l_u',leg:[['L','Vorschubweg in mm'],['l','Werkstücklänge in Vorschubrichtung in mm'],['l_a','Anlaufweg in mm'],['l_u','Überlaufweg in mm'],['i','Anzahl der Schnitte (bei mehreren Zustellungen)']],e:'Für mittiges Planfräsen gilt für den Anlaufweg l_a = 0,5 · (d − √(d² − a_e²)); a_e ist die Schnittbreite (Arbeitseingriff), d der Fräserdurchmesser.'}},
    {fx:{n:'Zeitspanvolumen beim Fräsen',tex:'Q = \\frac{a_p \\cdot a_e \\cdot v_f}{1000}',leg:[['Q','Zeitspanvolumen in cm³/min'],['a_p','Schnitttiefe in mm'],['a_e','Arbeitseingriff (Schnittbreite) in mm'],['v_f','Vorschubgeschwindigkeit in mm/min']]}},
    {bsp:{t:'Beispiel: Planfräsen eines Gussteils',b:['Gegeben: Fräser d = 80 mm, z = 6, vc = 200 m/min, fz = 0,15 mm, Werkstück 300 mm lang, a_e = 60 mm, a_p = 3 mm, ein Schnitt, Überlauf 2 mm','Drehzahl: n = 200 · 1000 / (π · 80) = 796 min⁻¹','Vorschubgeschwindigkeit: vf = 0,15 · 6 · 796 = 716 mm/min','Anlaufweg: la = 0,5 · (80 − √(80² − 60²)) = 0,5 · (80 − 52,9) = 13,5 mm','Vorschubweg: L = 300 + 13,5 + 2 = 315,5 mm','Hauptnutzungszeit: th = 315,5 / 716 = 0,44 min','Zeitspanvolumen: Q = 3 · 60 · 716 / 1000 = 128,9 cm³/min']}},
    {ul:['Gleichlauffräsen: Schneide dringt dick ein, Span wird dünn; geringerer Verschleiß, besser für CNC-Maschinen mit spielfreiem Vorschub','Gegenlauffräsen: Schneide dringt dünn ein, Span wird dick; die Schneide gleitet zunächst, die Werkstückhaut (Guss, Schmiedehaut) wird dabei besser unterschnitten','Stirnfräsen (Planfräsen) für ebene Flächen; Umfangsfräsen (Walzenfräsen) für Nuten und Seitenflächen','Wendeschneidplatten am Planfräskopf: Einstellwinkel 45° ergibt dünnere Späne bei gleichem Vorschub, 90° ergibt rechtwinklige Absätze']},
    {falle:'Beim Fräsen Vorschub je Zahn mal Zähnezahl rechnen – wer mit f je Umdrehung statt fz rechnet, erhält einen Vorschub, der um den Faktor z zu klein ist. Und die Leistung wird nur für die gleichzeitig im Eingriff befindlichen Zähne berechnet.'}]},

  {t:'Bohren, Senken, Reiben und Gewinde',h:'Vorschub, Hauptnutzungszeit, Kraft und Leistung beim Bohren',b:[
    {p:'Beim Bohren aus dem Vollen arbeiten zwei Schneiden gleichzeitig. Jede Schneide trägt den halben Vorschub ab und liegt im Mittel bei einem Viertel des Durchmessers vom Mittelpunkt entfernt.'},
    {fx:{n:'Hauptnutzungszeit Bohren',tex:'t_h = \\frac{L}{f \\cdot n} \\qquad L = l + l_a + l_u \\qquad l_a \\approx 0{,}3 \\cdot d',leg:[['L','Bohrweg in mm'],['l','Bohrtiefe in mm'],['l_a','Anbohrweg in mm (bei 118° Spitzenwinkel ca. 0,3 · d)'],['l_u','Überlauf in mm (nur bei Durchgangsbohrung)'],['f','Vorschub in mm'],['n','Drehzahl in min⁻¹']]}},
    {fx:{n:'Spanungsquerschnitt je Schneide',tex:'A = \\frac{d}{2} \\cdot \\frac{f}{2} = \\frac{d \\cdot f}{4}',leg:[['A','Spanungsquerschnitt einer Schneide in mm²'],['d','Bohrerdurchmesser in mm'],['f','Vorschub je Umdrehung in mm']]}},
    {fx:{n:'Drehmoment und Leistung beim Bohren',tex:'M_c = F_c \\cdot \\frac{d}{2} \\qquad P_c = M_c \\cdot 2\\pi \\cdot n',leg:[['M_c','Bohrmoment in Nm (bei F in N und d in m)'],['F_c','Schnittkraft einer Schneide in N'],['d','Bohrerdurchmesser in m'],['n','Drehzahl in s⁻¹ (min⁻¹ : 60)']],e:'Zwei Schneiden im Hebelarm d/4 ergeben zusammen F · d/2.'}},
    {bsp:{t:'Beispiel: Sacklochbohrung',b:['Gegeben: Ø 10 mm, Bohrtiefe 30 mm, vc = 60 m/min, f = 0,15 mm','Drehzahl: n = 60 · 1000 / (π · 10) = 1910 min⁻¹','Anbohrweg: la = 0,3 · 10 = 3 mm; Bohrweg L = 30 + 3 = 33 mm','Hauptnutzungszeit: th = 33 / (0,15 · 1910) = 0,115 min ≈ 6,9 s']}},
    {ul:['Aufbohren und Senken: Vergrößern oder Formen vorhandener Bohrungen, Zentrierung beachten','Reiben: Feinbearbeitung, Zugabe nur 0,1 bis 0,3 mm, Toleranz bis IT7 (H7)','Gewindebohren: Kernlochdurchmesser = Nenndurchmesser − Steigung (M10: 8,5 mm)','Kernlochdurchmesser für M8: 6,8 mm; M12: 10,2 mm','Bohrerwinkel 118° für Stahl, 140° bei Aluminium und Hartstoffen','Tieflochbohren ab Bohrtiefe über 5 · d: Kühlschmierstoff durch den Bohrer, Spanabfuhr beachten']},
    {falle:'Beim Bohren ist die Schnittgeschwindigkeit auf den Bohrerdurchmesser bezogen, nicht auf das Werkstück. Beim Einsatz in Aluminium wird oft zu langsam gebohrt – hohe vc, kleiner Vorschub, scharfe Schneide.'}]},

  {t:'Schleifen',h:'Schleifscheiben-Bezeichnung und Hauptnutzungszeit beim Außenrundschleifen',b:[
    {p:'Schleifen ist Trennen mit geometrisch unbestimmter Schneide. Es erzeugt kleine Toleranzen (IT5 bis IT6) und feine Oberflächen (Rz 1 bis 4 µm). Die Schleifscheibe ist ein Werkzeug aus Schleifkorn und Bindung; ihre Bezeichnung nach DIN ISO 603 beschreibt Form, Maße und Aufbau.'},
    {tab:[['Angabe','Bedeutung','Beispiel'],['Form','Grundform der Scheibe','1 = gerade Scheibe'],['Maße','Außendurchmesser – Breite – Bohrung','300 – 20 – 76,2 mm'],['Schleifmittel','Korund (A), Siliciumcarbid (C), CBN (kubisches Bornitrid), Diamant (D)','CBN für gehärteten Stahl, Diamant für Hartmetall'],['Körnung','Kornfeinheit: kleine Zahl = grob, große Zahl = fein','F80 = mittel-fein'],['Härte','Festigkeit der Bindung: A (sehr weich) bis Z (sehr hart)','K bis M = mittel'],['Bindung','Kornhalt: keramisch (V), Kunstharz (B), Metall (M)','M = Metallbindung']]},
    {fx:{n:'Hauptnutzungszeit Längs-Außenrundschleifen',tex:'t_h = \\frac{L \\cdot i}{n_w \\cdot f} \\qquad n_w = \\frac{v_w \\cdot 1000}{\\pi \\cdot d}',leg:[['L','Vorschubweg in mm (Länge der Schleifstelle abzüglich Überlauf bzw. zuzüglich Anlauf)'],['i','Anzahl der Schnitte (Zugabe : Zustellung)'],['n_w','Werkstückdrehzahl in min⁻¹'],['f','Längsvorschub je Werkstückumdrehung in mm'],['v_w','Werkstückgeschwindigkeit in m/min'],['d','Werkstückdurchmesser in mm']],e:'Längsvorschub beim Schruppen 0,5 bis 0,75 · bs, beim Schlichten meist 0,5 · bs (bs = Scheibenbreite).'}},
    {fx:{n:'Anzahl der Schnitte',tex:'i = \\frac{d_1 - d_2}{2 \\cdot a_p}',leg:[['d_1','Durchmesser vor dem Schleifen in mm'],['d_2','Fertigdurchmesser in mm'],['a_p','Zustellung je Schnitt (radial) in mm']],e:'Die Durchmesserzugabe wird radial zugestellt, deshalb geteilt durch 2 · a_p.'}},
    {bsp:{t:'Beispiel: Lagerstelle Ø 50 mm fertigschleifen',b:['Gegeben: l = 80 mm, Scheibenbreite bs = 25 mm, f = ½ · bs = 12,5 mm, vw = 20 m/min, Zugabe 0,2 mm auf den Durchmesser, ap = 0,02 mm, einseitiger Überlauf bs/3','Werkstückdrehzahl: nw = 20 · 1000 / (π · 50) = 127,3 min⁻¹','Anzahl Schnitte: i = 0,2 / (2 · 0,02) = 5','Vorschubweg: L = 80 − 25/3 = 71,7 mm','Hauptnutzungszeit: th = 71,7 · 5 / (127,3 · 12,5) = 0,225 min ≈ 13,5 s']}},
    {ul:['Außenrundschleifen: Längsschleifen (Pendeln) und Einstechschleifen (kein Längsvorschub)','Innenrundschleifen: kleinere Scheibe, geringere Schnittgeschwindigkeit nötig','Flachschleifen: Umfangs- oder Seitenschleifen, Werkstück auf Magnetspanntisch','Spitzenloses Schleifen: kein Aufspannen, hohe Stückzahlen','Abrichten: Scheibe wird wieder rund und scharf gemacht; Kühlschmierstoff verhindert Schleifbrand']},
    {falle:'Schleifbrand (Anlassfarben, Härteverlust, Risse) entsteht bei zu hoher Zustellung, stumpfer Scheibe oder zu wenig Kühlung – nicht durch zu feine Körnung. Grobe Körnung und weiche Bindung für weiche, zähe Werkstoffe; feine Körnung und harte Bindung für harte, spröde Werkstoffe.'}]},
  {"t":"Werkstoffkunde: Stahl, Gusseisen, NE-Metalle, Kunststoffe","h":"Bezeichnungen, Zugversuch, Härteprüfung, typische Kennwerte","b":[{"p":"Wer Fertigungsverfahren auswählt, muss den Werkstoff kennen: Er bestimmt Zerspanbarkeit, Wärmebehandlung, Schweißeignung und Kosten. Stahl hat weniger als 2,1 % Kohlenstoff und ist umformbar; Gusseisen hat mehr als 2,1 % Kohlenstoff und wird gegossen. Mit steigendem C-Gehalt nehmen Festigkeit und Härte zu, Zähigkeit, Dehnung und Schweißbarkeit nehmen ab."},{"tab":[["Bezeichnung","Bedeutung (DIN EN 10027)"],["S235JR","S = Baustahl, 235 = Mindeststreckgrenze Re in N/mm², JR = Kerbschlagarbeit 27 J bei 20 °C"],["C45","unlegierter Stahl, Kennzahl 45 = 0,45 % C (Kennzahl : 100)"],["42CrMo4","niedriglegiert: 0,42 % C; Cr 4 : 4 = 1 %; Mo ist enthalten (ca. 0,2 %), sein Gehalt steht nicht in der Bezeichnung"],["X5CrNi18-10","hochlegiert (X): 0,05 % C, 18 % Cr, 10 % Ni, nichtrostend"],["GJL-250","Gusseisen mit Lamellengraphit, Rm min. 250 N/mm²"],["GJS-400-15","Gusseisen mit Kugelgraphit, Rm min. 400 N/mm², Bruchdehnung 15 %"]]},{"p":"Bei legierten Stählen (Legierungsanteil unter 5 %) wird der Gehalt der Legierungselemente mit einem Faktor multipliziert angegeben: Faktor 4 für Cr, Co, Mn, Ni, Si, W; Faktor 10 für Al, Cu, Mo, Ti, V; Faktor 100 für C-nahe Elemente wie N, P, S; Faktor 1000 für B. Der Prozentgehalt ist die Zahl geteilt durch den Faktor."},{"merke":"Unlegiert: C und Zahl = C-Gehalt in Hundertstel Prozent. Niedriglegiert: Zahl = C-Gehalt in Hundertstel Prozent, danach Elemente, dann Gehalte mit Faktor. Hochlegiert: X vorn, danach C-Gehalt, Elemente und Prozentgehalte direkt."},{"h":"Zugversuch"},{"p":"Eine genormte Probe wird bis zum Bruch gezogen. Aus Kraft und Querschnitt entsteht das Spannungs-Dehnungs-Diagramm."},{"fx":{"n":"Spannung und Dehnung","tex":"\\sigma = \\frac{F}{S_0} \\qquad \\varepsilon = \\frac{\\Delta L}{L_0}","leg":[["\\sigma","Spannung in N/mm²"],["F","Zugkraft in N"],["S_0","Anfangsquerschnitt in mm²"],["\\varepsilon","Dehnung (ohne Einheit oder in %)"],["\\Delta L","Längenänderung in mm"],["L_0","Anfangsmesslänge in mm"]]}},{"tab":[["Kennwert","Zeichen","Bedeutung"],["Streckgrenze","Re (ReH)","Spannung, ab der der Werkstoff bleibend fließt"],["0,2-%-Dehngrenze","Rp0,2","Ersatz für Re bei Werkstoffen ohne ausgeprägte Streckgrenze (Aluminium, gehärteter Stahl)"],["Zugfestigkeit","Rm","größte Spannung im Versuch, bezogen auf S0"],["Bruchdehnung","A","bleibende Verlängerung nach dem Bruch in % von L0 (Maß für Verformbarkeit)"],["Brucheinschnürung","Z","Querschnittsabnahme an der Bruchstelle in % von S0"],["Elastizitätsmodul","E","Steigung im elastischen Bereich; Stahl ca. 210 000 N/mm², Aluminium ca. 70 000 N/mm²"]]},{"bsp":{"t":"Beispiel: Festigkeitsklasse einer Schraube","b":["Festigkeitsklasse 10.9: Rm = 10 · 100 = 1000 N/mm²","Streckgrenzenverhältnis 0,9: Re = 0,9 · 1000 = 900 N/mm² (Zahl hinter dem Punkt · 10 · erste Zahl)","Bei 8.8: Rm = 800 N/mm², Re = 640 N/mm²"]}},{"h":"Härteprüfung"},{"tab":[["Verfahren","Eindringkörper","Einsatz","Merkmal"],["Brinell (HBW)","Hartmetallkugel","weiche bis mittelharte Werkstoffe, Guss, Rohteile","großer Eindruck, Durchmesser des Eindrucks wird gemessen; für Stahl gilt etwa Rm ≈ 3,5 · HB"],["Vickers (HV)","Diamantpyramide (136°)","alle Härten, dünne Schichten, Kleinlast","genaueste Messung; Diagonalen des Eindrucks werden ausgemessen"],["Rockwell (HRC)","Diamantkegel (120°)","gehärteter Stahl, Werkstückkontrolle in der Fertigung","Eindringtiefe wird direkt als Härtewert angezeigt, sehr schnell"]]},{"p":"Weitere Prüfungen: Kerbschlagbiegeversuch (Zähigkeit, besonders bei Kälte), Dauerschwingversuch nach Wöhler (Dauerfestigkeit bei schwingender Belastung), Bauteilprüfung zerstörungsfrei (Ultraschall, Magnetpulver, Farbeindring, Röntgen)."},{"h":"Nichteisenmetalle und Kunststoffe"},{"tab":[["Werkstoff","Dichte in kg/dm³","Eigenschaften und Einsatz"],["Stahl","7,85","Standardwerkstoff, hohe Festigkeit, rostet, magnetisch"],["Aluminium","2,7","leicht, korrosionsbeständig, gut zerspanbar, gute Wärme- und Stromleitung; Knetlegierungen AlMgSi, AlCuMg; Gussteile für Gehäuse"],["Titan","4,5","hohe Festigkeit bei geringem Gewicht, korrosionsfest, schlecht zerspanbar (Wärme geht nicht in den Span), teuer"],["Magnesium","1,74","leichtester Konstruktionswerkstoff, brennbare Späne beachten"],["Kupfer","8,9","beste elektrische Leitfähigkeit, Wärmeleiter"],["Messing (CuZn)","8,4 bis 8,7","gut zerspanbar, Armaturen, Hülsen"],["Bronze (CuSn)","ca. 8,8","Gleitlager, verschleißfest, gute Notlaufeigenschaften"]]},{"tab":[["Kunststoffgruppe","Aufbau","Verhalten","Beispiele"],["Thermoplaste","Fadenmoleküle, nicht vernetzt","schmelzbar, schweißbar, recycelbar","PE, PP, PA, PVC, POM"],["Duroplaste","engmaschig vernetzt","nicht schmelzbar, hart, spröde, temperaturbeständig","Phenolharz, Epoxidharz"],["Elastomere","weitmaschig vernetzt","gummielastisch, nicht schmelzbar","Gummi, Silikon"]]},{"falle":"Die Streckgrenze ist nicht die Zugfestigkeit. Zulässige Spannungen werden mit der Streckgrenze und einem Sicherheitsfaktor gerechnet (σzul = Re : S), nicht mit Rm. Und: Brinell und Rockwell dürfen nur im jeweils passenden Härtebereich verwendet werden."}]},
  {"t":"Wärmebehandlung von Stahl","h":"Glühen, Härten, Anlassen, Vergüten, Randschichtverfahren, Nitrieren","b":[{"p":"Durch gezieltes Erwärmen, Halten und Abkühlen verändert man das Gefüge und damit Härte, Festigkeit, Zähigkeit und Spannungszustand eines Stahls, ohne die Form zu ändern. Das Eisen-Kohlenstoff-Diagramm zeigt die Umwandlungstemperaturen: Oberhalb der Linie GSK liegt Austenit vor, der beim schnellen Abkühlen zu Martensit (sehr hart, spröde) umklappt."},{"tab":[["Verfahren","Ziel","Ablauf"],["Normalglühen","feinkörniges, gleichmäßiges Gefüge","über Umwandlungstemperatur (ca. 850 °C), halten, an ruhender Luft abkühlen"],["Weichglühen","gut zerspanbar, gut umformbar","knapp unter A1 (ca. 700 °C) lange halten; Zementit wird kugelig (kugeliger Zementit)"],["Spannungsarmglühen","Eigenspannungen abbauen (nach Schweißen, Zerspanen, Richten)","ca. 550 bis 650 °C, langsam abkühlen; Gefüge bleibt unverändert"],["Rekristallisationsglühen","Verfestigung nach Kaltumformung beseitigen","ca. 550 bis 700 °C"],["Diffusionsglühen","Seigerungen ausgleichen (Guss)","sehr hoch (1100 bis 1300 °C), lange"],["Härten","hohe Härte und Verschleißwiderstand","austenitisieren (30 bis 50 K über Umwandlung), halten, schnell abschrecken (Wasser, Öl, Luft, Polymer) → Martensit"],["Anlassen","Härtespannungen abbauen, Zähigkeit erhöhen","nach dem Härten erneut erwärmen (150 bis 650 °C); je höher, desto zäher und weicher"],["Vergüten","hohe Festigkeit bei guter Zähigkeit","Härten + Anlassen auf hohe Temperatur (500 bis 650 °C); Vergütungsstähle wie C45, 42CrMo4"]]},{"merke":"Ein Stahl ist härtbar, wenn er mehr als etwa 0,3 bis 0,4 % Kohlenstoff enthält. Härten ohne anschließendes Anlassen wird nie ausgeführt: Der Martensit ist zu spröde und voller Spannungen."},{"h":"Randschichtverfahren"},{"p":"Viele Bauteile brauchen eine harte, verschleißfeste Oberfläche und einen zähen Kern (Zahnräder, Wellen, Nocken). Dafür gibt es mehrere Wege:"},{"tab":[["Verfahren","Prinzip","Typisch"],["Flamm- und Induktionshärten","nur die Randschicht wird schnell erhitzt und abgeschreckt","Stähle mit 0,4 bis 0,6 % C (C45, 42CrMo4), Laufflächen, Wellenzapfen, Zahnflanken"],["Einsatzhärten","Randschicht aufkohlen (bei ca. 900 °C), dann härten und anlassen","Einsatzstähle mit ca. 0,15 % C (C15, 16MnCr5); harte Oberfläche 0,5 bis 2 mm, zäher Kern"],["Nitrieren","Stickstoff diffundiert bei ca. 500 bis 550 °C in die Oberfläche, es bilden sich harte Nitride","kaum Verzug, kein Abschrecken; hohe Verschleiß- und Korrosionsbeständigkeit"],["Plasmanitrieren","Nitrieren im Plasma (Glimmentladung, Vakuum)","präzise steuerbar, auch für Werkzeuge und Schmiedegesenke; geringe Schichtdicke, sehr verzugsarm"],["Carbonitrieren","gleichzeitig Kohlenstoff und Stickstoff","dünne Randschichten bei niedrigerem Temperaturniveau"]]},{"bsp":{"t":"Beispiel: Welle aus 42CrMo4","b":["Wellen müssen fest und zäh sein, Lagersitz verschleißfest.","Wärmebehandlung: Vergüten (Härten ca. 850 °C, Anlassen ca. 600 °C) für den Kern, danach Induktionshärten des Lagersitzes und Schleifen auf Endmaß.","Vor dem Härten Schruppen, nach dem Härten Schleifen: Härteverzug bleibt dadurch beherrschbar."]}},{"falle":"Härten verursacht Verzug und Maßänderung. Endbearbeitung (Schleifen) kommt deshalb nach der Wärmebehandlung; Nitrieren ist die verzugsärmste Methode. Spannungsarmglühen ändert die Härte nicht."}]},
  {"t":"Urformen: Gießen und Sintern","h":"Gießverfahren, Modelle, Schwindung, Gussfehler, Pulvermetallurgie","b":[{"p":"Urformen heißt, aus formlosem Stoff (Schmelze, Pulver) einen festen Körper zu erzeugen. Der Zusammenhalt wird erstmals geschaffen. Die wichtigsten Verfahren sind Gießen und Sintern; auch das additive Fertigen gehört dazu."},{"tab":[["Gießverfahren","Form","Typisch","Merkmale"],["Sandguss","verlorene Form (Sand), Dauermodell","Einzelteile, große Stückzahlen klein, Maschinenbett, Gehäuse","billig, große Teile möglich, raue Oberfläche, größere Toleranzen"],["Kokillenguss","Dauerform aus Stahl (Kokille)","mittlere Serien, Aluminium, Kupferlegierungen","bessere Oberfläche und Maßgenauigkeit, feines Gefüge"],["Druckguss","Dauerform, Schmelze unter hohem Druck","Großserie, dünnwandige Aluminium-, Zink-, Magnesiumteile","sehr maßgenau, dünne Wände, hohe Werkzeugkosten"],["Feinguss (Wachsausschmelzverfahren)","verlorenes Wachsmodell, Keramikschale","komplexe Formen, Turbinenschaufeln, hochfeste Legierungen","sehr genau, wenig Nacharbeit, teuer"],["Schleuderguss","rotierende Form","rotationssymmetrische Teile, Rohre, Buchsen","dichtes Gefüge ohne Kern"]]},{"p":"Beim Erstarren und Abkühlen schwindet das Metall. Das Modell muss deshalb um das Schwindmaß größer sein als das Gussteil (Stahlguss ca. 2 %, GJL ca. 1 %, Aluminium ca. 1,2 %). Dazu kommen Bearbeitungszugaben (Aufmaß) an Flächen, die später zerspant werden, sowie Formschrägen zum Entformen."},{"fx":{"n":"Modellmaß mit Schwindmaß","tex":"L_\\text{Modell} = L_\\text{Guss} \\cdot \\left(1 + \\frac{s}{100}\\right)","leg":[["L_\\text{Modell}","Länge am Modell in mm"],["L_\\text{Guss}","Länge am fertigen Gussteil (mit Aufmaß) in mm"],["s","Schwindmaß in %"]]}},{"h":"Gussfehler und gießgerechte Konstruktion"},{"ul":["Lunker: Hohlräume durch Volumenabnahme beim Erstarren (Speiser setzen, Massenanhäufungen vermeiden)","Gasporen: eingeschlossene Gase (Entlüftung, trockene Formstoffe)","Seigerung: Entmischung der Legierungselemente","Spannungsrisse: ungleichmäßiges Abkühlen, scharfe Ecken","Konstruktionsregeln: möglichst gleichmäßige Wanddicken, große Übergangsradien, Rippen statt Massenanhäufung, Formschrägen"]},{"h":"Sintern (Pulvermetallurgie)"},{"p":"Metallpulver wird gepresst und knapp unter der Schmelztemperatur gesintert; die Teilchen verbinden sich durch Diffusion. Vorteile: nahezu endkonturnahe Teile ohne Nacharbeit, hohe Stückzahlen, gezielte Porosität (selbstschmierende Lager, Filter), Werkstoffe mit sehr hohem Schmelzpunkt (Hartmetall). Nachteile: Pressdruck begrenzt die Teilegröße, Werkzeuge sind teuer, Festigkeit geringer als bei Vollmaterial. Sinterlager (Hybridlager) speichern Öl in den Poren und laufen wartungsarm."},{"merke":"Gießen eignet sich für komplizierte Hohlformen, Sintern für kleine Teile in großer Stückzahl, Feinguss für höchste Formkomplexität."}]},
  {"t":"Umformen: Schmieden, Walzen, Pressen, Tiefziehen, Biegen","h":"Kalt- und Warmumformung, Verfestigung, Ziehverhältnis, Rückfederung, Gesenkschmieden","b":[{"p":"Umformen verändert die Form eines festen Körpers bleibend, ohne Material abzutragen: Masse und Zusammenhalt bleiben erhalten. Entscheidend ist die Umformtemperatur im Vergleich zur Rekristallisationstemperatur des Werkstoffs (Stahl ca. 600 bis 700 °C)."},{"tab":[["","Kaltumformung","Warmumformung"],["Temperatur","unter Rekristallisationstemperatur","darüber (Stahl 900 bis 1250 °C)"],["Kräfte","hoch","gering"],["Werkstück","verfestigt (Härte, Festigkeit steigen, Dehnung sinkt), Maßhaltigkeit gut, Oberfläche glatt","keine Verfestigung, Zunder, größere Toleranzen, Gefüge wird feinkörnig"],["Beispiele","Tiefziehen, Biegen, Fließpressen, Kaltwalzen","Schmieden, Warmwalzen, Strangpressen"]]},{"h":"Wichtige Verfahren"},{"tab":[["Verfahren","Prinzip","Beispiele"],["Freiformschmieden","Werkstück wird zwischen ebenen oder einfachen Werkzeugen umgeformt","große Wellen, Einzelstücke"],["Gesenkschmieden","Werkstück füllt die Form (Gesenk) aus; Überschuss fließt als Grat ab","Kurbelwellen, Pleuel, Zahnräder; Faserverlauf folgt der Kontur, deshalb hohe Festigkeit"],["Walzen","Durchziehen zwischen rotierenden Walzen","Bleche, Profile, Bänder"],["Strangpressen","Material wird durch eine Matrize gepresst","Aluminiumprofile, Rohre"],["Fließpressen","Werkstoff fließt unter hohem Druck im geschlossenen Werkzeug (kalt)","Schrauben, Hülsen, Bolzen"],["Tiefziehen","Blechplatine wird mit Stempel durch einen Ziehring gezogen; Niederhalter verhindert Falten","Karosserieteile, Töpfe, Gehäuse"],["Biegen","Blech oder Rohr wird um einen Radius gebogen","Winkel, Gehäuse, Profile"]]},{"h":"Tiefziehen"},{"fx":{"n":"Ziehverhältnis","tex":"\\beta = \\frac{D}{d}","leg":[["\\beta","Ziehverhältnis"],["D","Durchmesser der Platine in mm"],["d","Stempeldurchmesser (Napfdurchmesser) in mm"]],"e":"Im ersten Zug ist bei Stahlblech etwa β ≤ 1,8 bis 2,0 möglich; bei größerem Wert reißt der Boden. Dann in mehreren Zügen mit Zwischenglühen ziehen."}},{"p":"Typische Fehler: Falten (Niederhalterkraft zu klein), Reißer am Boden (Niederhalter zu fest, Ziehverhältnis zu groß, Radius zu klein), Zipfelbildung (anisotropes Blech). Schmierstoff reduziert die Reibung."},{"h":"Biegen"},{"p":"Beim Biegen sind die Außenfasern gestreckt, die Innenfasern gestaucht, dazwischen liegt die neutrale Faser, die ihre Länge behält. Die gestreckte Länge wird auf der neutralen Faser gerechnet. Nach dem Entlasten federt das Werkstück zurück (Rückfederung): Man biegt deshalb um den Rückfederungswinkel weiter (Überbiegen). Der Mindestbiegeradius hängt von Werkstoff und Blechdicke ab; zu kleine Radien führen zu Rissen an der Außenseite."},{"fx":{"n":"Gestreckte Länge","tex":"L = l_1 + l_2 + \\frac{\\pi \\cdot \\alpha}{180°} \\cdot \\left(r + k \\cdot s\\right)","leg":[["l_1, l_2","gerade Schenkellängen in mm"],["\\alpha","Biegewinkel in Grad"],["r","Innenradius in mm"],["s","Blechdicke in mm"],["k","Lage der neutralen Faser (ca. 0,33 bis 0,5 · s)"]]}},{"bsp":{"t":"Beispiel: Gestreckte Länge eines Winkels","b":["Blech s = 3 mm, 90°-Biegung, r = 4 mm, Schenkel außen: 40 mm und 60 mm, k = 0,4.","Neutrale Faser: r + k · s = 4 + 1,2 = 5,2 mm","Bogenlänge: π · 90 / 180 · 5,2 = 8,17 mm","Innen gemessene Schenkellängen: 40 − 4 − 3 = 33 mm und 60 − 4 − 3 = 53 mm","Zuschnittlänge: 33 + 53 + 8,17 ≈ 94,2 mm"]}},{"falle":"Beim Gesenkschmieden entsteht der Grat als Überschuss, der danach abgeschert wird. Plasmanitrieren der Gesenke schützt gegen Verschleiß und Anschweißen, das Werkstück selbst wird nicht nitriert. Warmumformung verfestigt nicht, Kaltumformung schon."}]},
  {"t":"Schneide, Spanbildung, Verschleiß und Standzeit","h":"Winkel am Schneidkeil, Spanarten, Verschleißformen, Taylor-Gerade","b":[{"p":"Am Schneidkeil eines Zerspanwerkzeugs bestimmen Winkel, wie der Span abfließt und wie viel Kraft nötig ist. Die Summe der drei Hauptwinkel ist immer 90°."},{"tab":[["Winkel","Zeichen","Wirkung"],["Freiwinkel","α","verhindert Reibung der Freifläche am Werkstück; zu klein: Reibung und Wärme, zu groß: geschwächter Keil"],["Keilwinkel","β","bestimmt die Stabilität der Schneide; groß für harte Werkstoffe und Unterbrechungen"],["Spanwinkel","γ","bestimmt Spanabfluss und Schnittkraft; positiv: kleine Schnittkraft (weiche Werkstoffe, Aluminium), negativ: stabil (harte Werkstoffe, Unterbrechungen)"],["Einstellwinkel","κ","Winkel zwischen Hauptschneide und Vorschubrichtung; beeinflusst Spanungsdicke und Spanungsbreite, Radialkraft"],["Eckenwinkel","ε","Winkel an der Werkzeugspitze (Wendeschneidplatte 55°, 80°, 90°)"],["Neigungswinkel","λ","Lage der Hauptschneide, beeinflusst Spanablauf und Stoßempfindlichkeit"]]},{"fx":{"n":"Winkelsumme am Keil","tex":"\\alpha + \\beta + \\gamma = 90°","leg":[["\\alpha","Freiwinkel"],["\\beta","Keilwinkel"],["\\gamma","Spanwinkel"]]}},{"h":"Spanarten"},{"tab":[["Spanart","Entstehung","Folge"],["Fließspan","zähe Werkstoffe, hohe Schnittgeschwindigkeit, positiver Spanwinkel","gleichmäßige Oberfläche, aber lange Bandspäne (Gefahr: Spanstau) – Spanbrecher einsetzen"],["Scherspan","mittlere Zähigkeit, geringere vc","gute Spanbrechung, etwas raue Oberfläche"],["Reißspan","spröde Werkstoffe (Grauguss), keine Verformung","kurze Späne, raue Oberfläche"],["Lamellenspan","schwer zerspanbare Werkstoffe (Titan, hitzebeständige Legierungen)","schwankende Schnittkraft, hohe Werkzeugbeanspruchung"]]},{"h":"Verschleiß"},{"ul":["Freiflächenverschleiß (Verschleißmarkenbreite VB): Reibung der Freifläche am Werkstück, typisches Standzeitkriterium: VB = 0,3 mm","Kolkverschleiß (Spanfläche): Diffusion und Abrasion, vor allem bei hohen Schnittgeschwindigkeiten (Hartmetall im Stahl)","Aufbauschneide: Werkstoff verschweißt an der Schneide bei kleiner Schnittgeschwindigkeit; verschlechtert die Oberfläche; Gegenmaßnahme: vc erhöhen, positiveren Spanwinkel wählen, besser schmieren","Kerbverschleiß an der Nebenschneide, Kantenausbrüche (Unterbrechung, zu hohe Belastung), Risse durch Temperaturwechsel (Kammrisse beim Fräsen)"]},{"fx":{"n":"Standzeitgerade nach Taylor","tex":"T = C_T \\cdot v_c^{-k} \\qquad \\frac{T_2}{T_1} = \\left(\\frac{v_{c1}}{v_{c2}}\\right)^{k}","leg":[["T","Standzeit in min"],["v_c","Schnittgeschwindigkeit in m/min"],["C_T","Konstante für Werkstoffpaarung"],["k","Standzeitexponent: Hartmetall ca. 4, HSS ca. 8"]],"e":"Schon eine geringe Erhöhung der Schnittgeschwindigkeit verkürzt die Standzeit stark."}},{"bsp":{"t":"Beispiel: Schnittgeschwindigkeit erhöhen","b":["Hartmetall-Wendeplatte, k = 4, Standzeit bei vc = 200 m/min: T1 = 60 min.","Neu vc = 240 m/min (+20 %): T2 = 60 · (200 / 240)^4 = 60 · 0,482 = 28,9 min","Die Standzeit halbiert sich fast, das Zeitspanvolumen steigt nur um 20 %: Wirtschaftlich optimal ist die Schnittgeschwindigkeit, bei der die Gesamtkosten pro Werkstück am geringsten sind – meist unter der zeitminimalen Geschwindigkeit."]}},{"merke":"Standzeit ist die Schnittzeit bis zum Erreichen des Verschleißkriteriums, Standmenge die in dieser Zeit gefertigte Stückzahl. Werkzeugwechselzeit und Werkzeugkosten gehören in die Kalkulation."},{"falle":"Aufbauschneide entsteht bei zu niedriger, nicht bei zu hoher Schnittgeschwindigkeit. Kolkverschleiß ist dagegen die Folge zu hoher Temperaturen. Spanwinkel und Freiwinkel dürfen nicht verwechselt werden: α an der Freifläche, γ an der Spanfläche."}]},
  {"t":"Schneidstoffe und Wendeschneidplatten","h":"HSS, Hartmetall, Keramik, CBN, PKD, Beschichtungen, ISO-Bezeichnung","b":[{"p":"Der Schneidstoff muss härter sein als der Werkstoff, bei hohen Temperaturen hart bleiben (Warmhärte), zäh genug für Stöße sein und verschleißen wenig. Härte und Zähigkeit stehen im Gegensatz: Je härter ein Schneidstoff, desto spröder ist er."},{"tab":[["Schneidstoff","Eigenschaften","Einsatz","Schnittgeschwindigkeit"],["Werkzeugstahl (HSS)","zäh, schleifbar, Warmhärte bis ca. 600 °C","Bohrer, Fräser, Gewindebohrer, Formwerkzeuge, kleine Stückzahlen","niedrig"],["Hartmetall (HM)","Wolframcarbid mit Kobalt als Bindemetall; hart, warmfest bis ca. 900 °C","Standardschneidstoff für Drehen und Fräsen","mittel bis hoch"],["beschichtetes Hartmetall","HM mit Schichten aus TiN, TiCN, Al2O3 (CVD/PVD)","höhere Standzeit und Schnittgeschwindigkeit","hoch"],["Cermet","TiC/TiN mit Nickelbindung","Schlichten von Stahl, gute Oberflächen","hoch"],["Schneidkeramik","Al2O3 oder Si3N4; sehr hart, spröde","Grauguss, gehärteter Stahl, hohe Geschwindigkeit, ohne Kühlschmierstoff","sehr hoch"],["CBN (kubisches Bornitrid)","härteste Schneidstoff nach Diamant, chemisch stabil gegen Eisen","gehärteter Stahl (ab ca. 45 HRC), Hartdrehen statt Schleifen","sehr hoch"],["PKD (polykristalliner Diamant)","höchste Härte, löst sich bei Eisen","Aluminium, Kupfer, Kunststoffe, CFK; nie für Stahl","sehr hoch"]]},{"h":"Anwendungsgruppen nach ISO 513"},{"tab":[["Buchstabe","Farbe","Werkstoffgruppe"],["P","blau","Stahl, Stahlguss (langspanend)"],["M","gelb","nichtrostender Stahl, Austenit"],["K","rot","Gusseisen (kurzspanend)"],["N","grün","Nichteisenmetalle (Aluminium, Kupfer)"],["S","braun","hitzebeständige Legierungen, Titan"],["H","grau","gehärtete Werkstoffe"]]},{"h":"Wendeschneidplatten (ISO 1832)"},{"p":"Die Bezeichnung besteht aus Zeichen mit festgelegter Bedeutung, zum Beispiel CNMG 120408:"},{"tab":[["Stelle","Zeichen","Bedeutung"],["1","C","Form: Raute 80°"],["2","N","Freiwinkel 0° (Negativplatte)"],["3","M","Toleranzklasse"],["4","G","Spanleitstufe, Befestigung (Bohrung)"],["5","12","Schneidenlänge in mm"],["6","04","Dicke in mm (04 = 4,76 mm)"],["7","08","Eckenradius 0,8 mm"]]},{"merke":"Negativplatten (Freiwinkel 0°) haben beidseitig nutzbare Schneiden und sind stabil; sie werden mit negativem Einbauwinkel geklemmt. Positivplatten schneiden leichter, sind aber nur einseitig nutzbar."},{"falle":"Ein größerer Eckenradius verbessert die Oberfläche (Rautiefe theoretisch Rz = f² / (8 · r)) und die Stabilität, erhöht aber die Radialkraft und die Schwingungsneigung. Bei schlanken Wellen deshalb eher kleinen Radius wählen."}]},
  {"t":"Kühlschmierstoffe, MMS und Trockenbearbeitung","h":"Aufgaben, Arten, Pflege, Entsorgung, Gesundheitsschutz, Kosten","b":[{"p":"Kühlschmierstoffe (KSS) haben drei Aufgaben: Schmieren (Reibung und Aufbauschneide verringern), Kühlen (Wärme aus Werkzeug, Werkstück und Span abführen) und Spülen (Späne aus der Schnittzone transportieren). Sie schützen außerdem Werkstück und Maschine vor Korrosion."},{"tab":[["Art","Beispiele","Eigenschaft"],["wassermischbar","Emulsion (Öl in Wasser), Lösung","gute Kühlwirkung; Pflege nötig (Konzentration 5 bis 8 %, pH-Wert ca. 8,5 bis 9,5)"],["nicht wassermischbar","Schneidöl","sehr gute Schmierung, geringe Kühlung, Brandgefahr, Nebelbildung"],["Minimalmengenschmierung (MMS)","Aerosol aus Luft und wenigen ml Öl pro Stunde direkt an der Schneide","kein Kühlschmierstoff-Kreislauf, trockene Späne und Teile, keine Entsorgung; kaum Kühlwirkung"],["Trockenbearbeitung","kein KSS","nur mit geeigneten Schneidstoffen (Hartmetall, Keramik, CBN) und hoher Geschwindigkeit, Wärme geht in den Span"]]},{"h":"Pflege und Überwachung"},{"ul":["Konzentration mit Refraktometer prüfen, pH-Wert messen (zu niedrig: Korrosion, Bakterien; zu hoch: Hautreizung)","Verunreinigungen (Fremdöl, Späne, Schlamm) abscheiden, Filteranlagen warten","Keime und Pilze: regelmäßig prüfen, Nachbeimischung, Belüftung; Kühlschmierstoff nie über Wochenende stagnieren lassen","Wechsel nach Plan; Altöl und KSS-Emulsionen sind Sonderabfall und werden durch zugelassene Entsorger abgeholt (Abfallschlüssel, Nachweis)"]},{"h":"Gesundheitsschutz"},{"p":"KSS gehören zu den Gefahrstoffen. Hautschutz und Hautpflege (Hautschutzplan), Handschuhe, Absaugung gegen Nebel und Dämpfe, Betriebsanweisung und Unterweisung sind Pflicht (TRGS 611, Gefahrstoffverordnung). Typische Erkrankungen: Hautekzeme, Atemwegsreizungen."},{"bsp":{"t":"Beispiel: Kostenvergleich Nass gegen MMS","b":["Kosten der Nassbearbeitung: Konzentrat, Prüfung und Wartung, Entsorgung des Tankinhalts, Arbeitszeit für Entsorgung.","MMS: Anschaffung des Sprühsystems (mit Abschreibung und Zinsen), MMS-Öl, geringe Wartung, keine Entsorgungskosten.","Entscheidung über die Amortisation: Kostenersparnis + Abschreibung = jährlicher Rückfluss; Amortisationsdauer = Anschaffung : Rückfluss."]}},{"falle":"Trockenbearbeitung heißt nicht „ohne Wärme“: Die Wärme steckt im Span, deshalb hohe Geschwindigkeit und Späneabfuhr beachten. MMS ersetzt nicht jedes Verfahren – beim Tiefbohren und Schleifen ist Kühlung meist unverzichtbar."}]},
  {"t":"Schweißen: Verfahren, Schutzgase und Nahtarten","h":"Schmelzschweißen im Überblick","b":[{"p":"Beim Schmelzschweißen werden die Fügeteile örtlich aufgeschmolzen und mit oder ohne Zusatzwerkstoff zu einer unlösbaren Verbindung vereint. Die Verfahren unterscheiden sich in Wärmequelle, Schutz der Schmelze und Automatisierbarkeit."},{"tab":[["Verfahren","Kurzzeichen (DIN EN ISO 4063)","Merkmale","Typischer Einsatz"],["Lichtbogenhandschweißen","111","umhüllte Stabelektrode, Schlacke schützt die Naht","Montage, Reparatur, Baustelle"],["Metall-Schutzgasschweißen (MIG/MAG)","131 / 135","abschmelzende Drahtelektrode, hohe Abschmelzleistung, gut mechanisierbar","Serienfertigung Stahl und Aluminium"],["Wolfram-Inertgasschweißen (WIG)","141","nicht abschmelzende Wolframelektrode, Zusatzstab von Hand, sehr saubere Naht","Edelstahl, Aluminium, dünne Bleche, Rohre"],["Unterpulverschweißen","121","Lichtbogen unter Pulverschicht, große Nahtquerschnitte","dicke Bleche, Behälterbau"],["Widerstandspunktschweißen","21","Strom durch Fügeteile, Elektrodenkraft, kein Zusatzwerkstoff","Karosserie, dünne Bleche"],["Laserstrahlschweißen","52","hohe Energiedichte, schmale tiefe Naht, geringer Verzug","Präzisionsteile, Automobil"]]},{"merke":"MIG = Metall-Inertgas (Argon, Helium; für Aluminium, Kupfer). MAG = Metall-Aktivgas (CO₂ oder Argon-Mischgas mit CO₂/O₂; für un- und niedriglegierten Stahl). WIG kennt kein abschmelzendes Elektrodendraht-Prinzip."},{"p":"Das Schutzgas verhindert, dass Sauerstoff und Stickstoff der Luft in die Schmelze gelangen (Poren, Oxide). Reines Argon ist inert; Zusätze von CO₂ oder O₂ stabilisieren den Lichtbogen und verbessern den Einbrand bei Stahl."},{"ul":["Stumpfnaht (I-, V-, X-Naht): Teile liegen in einer Ebene, Nahtvorbereitung nach Blechdicke","Kehlnaht: Teile im Winkel (T-Stoß, Überlappstoß), Nahtdicke a als Höhe des einschreibbaren Dreiecks","Schweißposition (PA Wannenlage bis PF/PG Steigend/Fallend): Position und Lage beeinflussen die Schweißbarkeit und die Prüfung der Schweißer","Schweißeignung hängt von Werkstoff (Kohlenstoffäquivalent), Konstruktion und Fertigung ab"]},{"p":"Wärmeeinbringung führt zu Schrumpfung und Verzug. Gegenmaßnahmen: Heften in Wechselfolge, Gegenschweißen, symmetrischer Nahtaufbau, Vorrichtungen, Wärmearme Verfahren (Laser), Spannungsarmglühen bei kritischen Bauteilen."},{"falle":"Schweißen gehört nach DIN 8580 zum Fügen, auch wenn Werkstoff aufgeschmolzen wird. Aluminium lässt sich nicht mit CO₂-haltigem Schutzgas (MAG) schweißen, sondern nur mit inerten Gasen (MIG/WIG)."}]},
  {"t":"Löten und Kleben","h":"Stoffschlüssige Verbindungen ohne Aufschmelzen der Grundwerkstoffe","b":[{"p":"Beim Löten wird nur das Lot aufgeschmolzen, die Grundwerkstoffe bleiben fest. Die Schmelztemperatur des Lots liegt unter der der Fügeteile. Das Lot benetzt die Oberfläche und fließt im Lötspalt durch Kapillarwirkung."},{"tab":[["Löten","Arbeitstemperatur","Merkmale"],["Weichlöten","unter 450 °C","Zinn-Lote, Elektronik, Klempnerarbeiten, geringe Festigkeit"],["Hartlöten","über 450 °C","Messing-, Silber-, Kupferlote, höhere Festigkeit, Rohrverbindungen, Hartmetallplatten auf Stahl"],["Hochtemperaturlöten","über 900 °C (Vakuum / Schutzgas)","flussmittelfrei, hochfeste Verbindungen"]]},{"ul":["Flussmittel löst Oxide und schützt die Lötstelle; Rückstände sind oft korrosiv und müssen entfernt werden","Lötspalt 0,05 bis 0,2 mm: zu enger Spalt – Lot dringt nicht ein, zu weiter Spalt – geringe Festigkeit","Lötstellen sind zu entfetten und blank zu machen"]},{"p":"Kleben verbindet Fügeteile durch Adhäsion (Haftung an der Oberfläche) und Kohäsion (Festigkeit des Klebstoffs). Die Verbindung ist gleichmäßig belastbar, ohne Wärmeeinfluss und verbindet unterschiedliche Werkstoffe."},{"ul":["Reaktionsklebstoffe (Epoxid, Polyurethan, Acrylat): hohe Festigkeit, Aushärten durch chemische Reaktion","Kleben auf Schub und Zug beanspruchen, Schälbelastung vermeiden","Oberflächenvorbehandlung (Entfetten, Anrauen, Primer) entscheidet über die Festigkeit","Aushärtezeit und Temperatur des Herstellers einhalten"]},{"merke":"Klebeverbindungen: große Überlappungsfläche, Belastung in der Klebefläche (Schub), Schälen vermeiden. Löten: Lot schmilzt, Grundwerkstoff nicht. Schweißen: Grundwerkstoff schmilzt."},{"falle":"Löten ist kein Schweißen: Beim Löten bleibt der Grundwerkstoff fest. Hartlöten beginnt über 450 °C, nicht bei der Schmelztemperatur der Teile."}]},
  {"t":"Schraubenverbindungen","h":"Festigkeitsklasse, Vorspannkraft und Sicherung","b":[{"p":"Schrauben erzeugen Kraftschluss durch Vorspannkraft: Die Schraube wird gedehnt, die Bauteile werden zusammengepresst. Betriebskräfte werden über Reibung zwischen den Bauteilen (Reibschluss) oder über den Schaft (Formschluss, Passschraube) übertragen."},{"fx":{"n":"Festigkeitsklasse","tex":"R_m = a \\cdot 100\\ \\mathrm{N/mm^2},\\quad R_e = a \\cdot b \\cdot 10\\ \\mathrm{N/mm^2}","leg":[["a","erste Zahl der Festigkeitsklasse"],["b","zweite Zahl (Streckgrenzenverhältnis ·10)"]],"e":"Beispiel 8.8: Rm = 800 N/mm², Re = 8 · 8 · 10 = 640 N/mm². Beispiel 12.9: Rm = 1200, Re = 1080 N/mm²."}},{"fx":{"n":"Erforderliche Vorspannkraft bei Reibschluss","tex":"F_V = \\frac{S_R \\cdot F_B}{\\mu \\cdot n}","leg":[["F_V","Vorspannkraft in N"],["S_R","Rutschsicherheit"],["F_B","Betriebs-(Quer-)kraft in N"],["μ","Reibungszahl in den Trennfugen"],["n","Anzahl der reibenden Trennfugen (bei einer Fuge 1)"]],"e":"Je kleiner die Reibungszahl, desto größer muss die Vorspannkraft sein."}},{"fx":{"n":"Zulässige Spannung und Betriebskraft der Schraube","tex":"\\sigma_{zul} = \\frac{R_e}{S},\\quad F = A_s \\cdot \\sigma_{zul}","leg":[["σ_zul","zulässige Spannung in N/mm²"],["S","Sicherheitsfaktor"],["A_s","Spannungsquerschnitt in mm² (Tabellenbuch)"]],"e":"Der Spannungsquerschnitt steht im Tabellenbuch zum Gewinde (z. B. M24: 353 mm², M24x2: 384 mm²)."}},{"ul":["Dehnschrauben haben einen langen dünnen Schaft: hohe Elastizität, sichere Vorspannung auch bei Setzen und Temperaturschwankungen, hohe Dauerfestigkeit","Anziehen mit Drehmomentschlüssel oder drehwinkelgesteuert; Anziehdrehmoment hängt von Reibung ab (Schmierung ändern verfälscht Vorspannkraft)","Sicherungen: Losdrehsicherung (Klebstoff, Sperrzahn), Verliersicherung (Splint, Kronenmutter); Federscheiben allein sind keine zuverlässige Sicherung","Setzverlust: Rauheiten glätten sich, Vorspannkraft sinkt – nachziehen bei kritischen Verbindungen"]},{"merke":"Reibschluss: Querkraft wird über Reibung übertragen, deshalb Vorspannkraft hoch. Passschraube: Formschluss, Querkraft belastet den Schaft auf Abscheren und Lochleibung."},{"falle":"Die Festigkeitsklasse 12.9 bedeutet Rm = 1200 N/mm², nicht 12 N/mm². Der Spannungsquerschnitt wird dem Tabellenbuch entnommen, nicht aus dem Nenndurchmesser berechnet."}]},
  {"t":"Thermisches Trennen: Brennschneiden, Plasma, Laser, Wasserstrahl","h":"Konturen aus Blech schneiden","b":[{"tab":[["Verfahren","Prinzip","Werkstoffe","Besonderheiten"],["Autogen-Brennschneiden","Flamme erwärmt auf Zündtemperatur, Sauerstoffstrahl verbrennt und bläst den Werkstoff aus","un- und niedriglegierter Stahl bis 300 mm und mehr","nur Stahl; Schnittfuge grob; Wärmeeinflusszone"],["Plasmaschneiden","Lichtbogen im Plasmagas schmilzt den Werkstoff, Gasstrahl bläst die Schmelze aus","alle elektrisch leitenden Metalle, auch Edelstahl und Aluminium","schnell, mittlere Schnittqualität"],["Laserstrahlschneiden","fokussierter Laserstrahl schmilzt oder verdampft, Schneidgas bläst aus","Stahl, Edelstahl, Aluminium, Kunststoffe; Bleche bis etwa 25 mm","sehr schmale Fuge, hohe Genauigkeit, geringer Verzug"],["Wasserstrahlschneiden","Wasser (mit Abrasivmittel) mit etwa 3000 bis 6000 bar trennt durch Erosion","fast alle Werkstoffe, auch Glas, Stein, Verbund","kalter Schnitt, keine Wärmeeinflusszone, langsamer"]]},{"p":"Beim Brennschneiden muss der Werkstoff in reinem Sauerstoff verbrennen können und die Zündtemperatur muss unter der Schmelztemperatur liegen; das Oxid muss dünnflüssiger als der Werkstoff sein. Das gilt für unlegierten Stahl, aber nicht für Edelstahl, Aluminium und Gusseisen."},{"fx":{"n":"Schneidzeit bei Brennschneiden","tex":"t = \\frac{L}{v_s}","leg":[["t","Schneidzeit in min"],["L","Schnittlänge der Kontur in mm (Summe aller Strecken und Bögen)"],["v_s","Schneidgeschwindigkeit in mm/min (aus Tabelle, hängt von der Blechdicke ab)"]],"e":"Konturlänge aus Geraden, Schrägen und Kreisbögen zusammensetzen; Anschnitte (Einstechen) für Innenkonturen mitrechnen, wenn die Aufgabe das verlangt."}},{"ul":["Schneidgeschwindigkeit sinkt mit der Blechdicke (dicker – langsamer)","Innenkonturen (Langlöcher, Bohrungen) vor der Außenkontur schneiden, damit das Blech sich nicht verzieht","Verzug und Wärmeeinfluss entstehen vor allem beim Brennschneiden; hohe Genauigkeit liefern Laser und Wasserstrahl","Schnittkanten von Brennschnitten können aufgehärtet sein – bei Weiterbearbeitung beachten"]},{"falle":"Brennschneiden funktioniert nur bei Werkstoffen, die in Sauerstoff verbrennen (unlegierter und niedriglegierter Stahl). Edelstahl und Aluminium werden mit Plasma, Laser oder Wasserstrahl getrennt."}]},
  {"t":"Scherschneiden und Feinschneiden","h":"Ausschneiden, Lochen und Schneidkraft","b":[{"p":"Beim Scherschneiden trennt ein Stempel das Blech gegen die Schneidplatte. Zwischen Stempel und Schneidplatte liegt der Schneidspalt. Der Schnittverlauf zeigt Kanteneinzug, Glattschnittanteil, Bruchfläche und Grat."},{"fx":{"n":"Schneidkraft","tex":"F = l \\cdot s \\cdot \\tau_{aB}","leg":[["F","Schneidkraft in N"],["l","Länge der Schnittlinie in mm (Umfang)"],["s","Blechdicke in mm"],["τ_aB","Abscherfestigkeit in N/mm² (etwa 0,8 · Rm)"]],"e":"Je größer Umfang und Blechdicke, desto größer die Schneidkraft. Mehrere Stempel gleichzeitig: Schnittlängen addieren oder Schneiden versetzt (gestaffelt) anordnen, um die Spitzenkraft zu senken."}},{"fx":{"n":"Schneidarbeit (vereinfacht)","tex":"W = F_{m} \\cdot s,\\quad F_m \\approx 0{,}6 \\ldots 0{,}7 \\cdot F_{max}","leg":[["W","Schneidarbeit in Nm (J)"],["F_m","mittlere Kraft"],["s","Blechdicke als Schneidweg"]],"e":"Die Pressenarbeit muss durch das Schwungrad der Presse geliefert werden."}},{"ul":["Schneidspalt etwa 5 bis 10 % der Blechdicke (bei Feinschneiden nahezu null)","Beim Ausschneiden bestimmt die Schneidplatte das Maß, beim Lochen der Stempel","Zu großer Schneidspalt: starker Grat, Einzug; zu kleiner: hoher Verschleiß, Doppelglattschnitt","Feinschneiden: Niederhalter und Gegenhalter, Ringzacke, sehr kleiner Spalt – fast vollständig glatte Schnittfläche, kein Grat"]},{"merke":"Ausschneiden: Maß der Schneidplatte, Lochen: Maß des Stempels – die jeweils andere Seite erhält den Schneidspalt als Zugabe."},{"falle":"Die Abscherfestigkeit ist nicht gleich der Zugfestigkeit: Näherungsweise τaB ≈ 0,8 · Rm. Wird in der Aufgabe τaB direkt genannt, damit rechnen."}]},
  {"t":"Abtragen: Funkenerosion und elektrochemisches Abtragen","h":"Verfahren für harte Werkstoffe und komplizierte Formen","b":[{"p":"Beim Funkenerosieren (EDM = Electrical Discharge Machining) trägt eine Folge elektrischer Entladungen zwischen Elektrode und Werkstück in einem Dielektrikum (Öl oder deionisiertes Wasser) Material ab. Nur elektrisch leitende Werkstoffe lassen sich bearbeiten – unabhängig von ihrer Härte."},{"tab":[["Verfahren","Merkmale","Anwendung"],["Senkerodieren","formgebende Elektrode (Graphit/Kupfer) wird in das Werkstück gesenkt; Elektrode verschleißt, bildet die Form spiegelverkehrt ab","Formen, Werkzeuge, Gesenke, Sacklöcher, komplexe Kavitäten"],["Drahterodieren","dünner Draht (0,02–0,3 mm) schneidet wie eine Bandsäge; Draht läuft kontinuierlich ab","Stempel, Schneidplatten, Konturen mit hoher Genauigkeit, Schrägen"],["ECM – Elektrochemisches Abtragen","Metall wird anodisch aufgelöst, kein Werkzeugverschleiß, keine thermische Beeinflussung","Turbinenschaufeln, Entgraten, Serienteile"]]},{"ul":["Vorteile: Bearbeitung gehärteter Werkstoffe, keine mechanischen Kräfte, komplizierte Konturen, hohe Genauigkeit","Nachteile: geringe Abtragleistung, Elektrodenverschleiß, Wärmeeinflusszone mit Rand-Rekristallisation (weiße Schicht), nur leitfähige Werkstoffe","Dielektrikum isoliert, kühlt und spült die abgetragenen Partikel aus dem Spalt"]},{"merke":"Erodieren ersetzt Fräsen, wenn der Werkstoff zu hart ist, die Form zu filigran (scharfe Innenecken) oder die Kräfte beim Zerspanen das Teil verformen würden."},{"falle":"Erodieren funktioniert nur bei elektrisch leitenden Werkstoffen. Keramik oder Kunststoff lassen sich nicht erodieren."}]},
  {"t":"CNC-Technik: Achsen, Nullpunkte, Programmaufbau","h":"Koordinaten, Bezugspunkte, G- und M-Befehle","b":[{"p":"CNC-Maschinen führen Werkzeug oder Werkstück nach einem Programm durch numerisch gesteuerte Achsen. Die Achsrichtungen sind nach DIN 66217 festgelegt: Die Z-Achse liegt in der Hauptspindel, die X-Achse ist die Hauptbewegungsrichtung quer dazu, Y ergänzt das rechtshändige Koordinatensystem."},{"tab":[["Punkt","Kürzel","Bedeutung"],["Maschinennullpunkt","M","vom Hersteller festgelegt, Ursprung des Maschinenkoordinatensystems"],["Referenzpunkt","R","Fahrpunkt zum Initialisieren der Messsysteme nach dem Einschalten"],["Werkstücknullpunkt","W","vom Programmierer bzw. Einrichter am Werkstück gewählt; Bezugspunkt der Maße im Programm"],["Werkzeugwechselpunkt","","sichere Position für Werkzeugwechsel"],["Werkzeugvoreinstellung","","Länge und Radius der Werkzeuge werden gemessen und als Korrekturwerte hinterlegt"]]},{"ul":["G-Befehle (Wegbedingungen): G0 Eilgang, G1 Linearinterpolation, G2 Kreis im Uhrzeigersinn, G3 gegen den Uhrzeigersinn, G40/G41/G42 Bahnkorrektur aus/links/rechts, G54 bis G59 Nullpunktverschiebungen","M-Befehle (Schaltbefehle): M3 Spindel rechts, M4 Spindel links, M5 Spindel aus, M6 Werkzeugwechsel, M8 Kühlmittel ein, M9 aus, M30 Programmende","Weitere Wörter: N Satznummer, T Werkzeug, S Drehzahl bzw. Schnittgeschwindigkeit, F Vorschub","Absolut- (G90) und Kettenmaß (G91): Absolut bezieht sich auf den Nullpunkt, Kettenmaß auf die letzte Position"]},{"p":"Werkzeugkorrekturen gleichen Länge und Radius aus. Die Schneidenradiuskorrektur (G41/G42) verschiebt die Bahn um den Radius, damit die Kontur genau getroffen wird. Verschleiß wird durch Korrekturwerte ausgeglichen, ohne das Programm zu ändern."},{"merke":"Programmablauf: Programm erstellen (Zeichnung, Arbeitsplan, Schnittwerte), simulieren, Nullpunkte und Werkzeuge einrichten, Probelauf (Einzelsatz, Vorschub reduziert), erst dann Serie. Die Simulation erspart Kollisionen und Ausschuss."},{"falle":"Absolutmaß G90 und Kettenmaß G91 nicht verwechseln: Ein falsch gewähltes Maßsystem verschiebt die gesamte Kontur. Beim Zirkular-Interpolieren die Drehrichtung (G2/G3) aus Sicht des Werkzeugs bestimmen."}]},
  {"t":"Industrieroboter","h":"Bauarten, Koordinatensysteme, Programmierung und Sicherheit","b":[{"tab":[["Bauart","Achsen","Arbeitsraum","Einsatz"],["Knickarmroboter","6 Drehachsen","kugelähnlich, großer Raum","Schweißen, Lackieren, Montage, Handhabung"],["SCARA-Roboter","Drehgelenke + 1 Hubachse","Zylinder, flach","schnelle Montage kleiner Teile, Pick and Place"],["Portalroboter (kartesisch)","3 Linearachsen","Quader","Beladen von Werkzeugmaschinen, hohe Lasten"],["Deltaroboter","3 parallele Arme","Kuppel, klein","sehr schnelles Sortieren und Verpacken"],["Cobot (kollaborativ)","meist 6 Achsen","wie Knickarm, mit Kraftbegrenzung","Mensch-Roboter-Zusammenarbeit ohne Schutzzaun"]]},{"ul":["Freiheitsgrade: Eine freie Bewegung im Raum erfordert 6 Freiheitsgrade (3 Positionen, 3 Orientierungen)","Koordinatensysteme: Basis- (Roboterfuß), Welt-, Werkzeug- (TCP, Tool Center Point) und Werkstückkoordinatensystem","TCP: Punkt am Werkzeug, der programmiert und bewegt wird; muss nach Werkzeugwechsel neu vermessen werden","Programmierung: Teach-in (Punkte mit dem Handbediengerät anfahren und speichern), textuell/offline am PC, Simulation"]},{"p":"Sicherheit am Roboter richtet sich nach der Maschinenrichtlinie und DIN EN ISO 10218. Schutzeinrichtungen (Zaun mit Verriegelung, Lichtvorhang, Laserscanner) trennen Mensch und Roboter. Beim Teachen in der Zelle gilt reduzierte Geschwindigkeit (höchstens 250 mm/s) und die Zustimmungstaste am Handbediengerät."},{"ul":["Kollaborierende Roboter begrenzen Kraft und Leistung, dennoch ist für jede Anwendung eine Risikobeurteilung nötig (Werkzeug, Werkstück, Scharfkantigkeit)","Vier Arten der Kollaboration: sicherheitsgerichteter Stopp, Handführung, Geschwindigkeits- und Abstandsüberwachung, Leistungs- und Kraftbegrenzung","Wiederholgenauigkeit (wie genau wird derselbe Punkt wieder angefahren) ist nicht gleich der absoluten Genauigkeit"]},{"falle":"Wiederholgenauigkeit und absolute Positioniergenauigkeit sind verschiedene Kennwerte. Industrieroboter wiederholen sehr genau, aber ihre absolute Genauigkeit im Raum ist geringer."}]},
  {"t":"Additive Fertigung (3D-Druck)","h":"Verfahren, Ablauf und Nachbearbeitung","b":[{"p":"Additive Fertigungsverfahren bauen ein Bauteil Schicht für Schicht aus Pulver, Draht oder Kunststofffilament nach 3D-Daten auf. Nach DIN 8580 gehören sie zum Urformen. Die Teilegeometrie ist kaum begrenzt (Hohlräume, Gitterstrukturen, Kühlkanäle), Werkzeugkosten entfallen."},{"tab":[["Verfahren","Werkstoff","Prinzip","Merkmale"],["SLM / PBF-LB/M (Laserstrahlschmelzen im Pulverbett)","Metallpulver (Stahl, Titan, Aluminium)","Laser schmilzt Pulverschicht lokal, Bauplattform senkt sich, neue Schicht","dichte Bauteile, Stützstrukturen nötig, Nachbearbeitung der Funktionsflächen"],["SLS (Lasersintern)","Kunststoffpulver (PA)","Laser sintert Pulver, nicht verschmolzenes Pulver stützt das Bauteil","keine Stützen nötig, Pulver teilweise wiederverwendbar"],["FDM / FFF","Kunststoff-Filament","Düse extrudiert aufgeschmolzenen Strang","günstig, Prototypen, sichtbare Schichten"],["Binder Jetting","Pulver + Binder","Bindemittel verklebt Pulver, anschließend Sintern/Infiltrieren","schnell, Schwindung beachten"],["Stereolithografie","Photopolymer","UV-Licht härtet Harz schichtweise aus","feine Details, glatte Oberfläche"]]},{"ol":["3D-CAD-Modell erstellen, Bauteil im Bauraum ausrichten (Orientierung beeinflusst Stützen, Oberflächengüte, Eigenspannung)","Slicen: Schichten berechnen (Schichtdicke 20–100 µm), Laserparameter festlegen, Stützstrukturen generieren","Bauprozess unter Schutzgas (Argon/Stickstoff) starten, Pulver überwachen","Bauteil entpacken, Pulver entfernen, spannungsarm glühen, von der Bauplattform trennen","Stützen entfernen, Funktionsflächen zerspanen (Passungen), Oberflächen strahlen, prüfen"]},{"ul":["Eigenspannungen entstehen durch lokales Aufschmelzen und schnelles Abkühlen: Verzug und Risse – Spannungsarmglühen vor dem Abtrennen","Pulver ist feinstaubfähig: Explosions- und Gesundheitsgefahr (Metallpulver, Schutzgas, Absaugung, Erdung, Schutzkleidung)","Wirtschaftlich besonders bei kleinen Stückzahlen, hoher Komplexität und Leichtbau","Wiederverwendbares Restpulver wird gesiebt; Klümpchenbildung macht einen Teil unbrauchbar"]},{"falle":"Additive Fertigung heißt nicht nachbearbeitungsfrei: Passungen, Dichtflächen und Gewinde werden meist zerspanend nachbearbeitet. Das Aufbauen ohne Stützen ist nicht bei allen Überhängen möglich."}]},
  {"t":"Beschichten und Oberflächentechnik","h":"Schutz, Verschleiß und Optik","b":[{"tab":[["Verfahren","Prinzip","Beispiele"],["Lackieren, Pulverbeschichten","organische Schicht, Pulver wird elektrostatisch aufgetragen und eingebrannt","Gehäuse, Stahlbau"],["Feuerverzinken","Eintauchen in flüssiges Zink, Schichtdicke etwa 50–100 µm","Stahlbau, Schrauben"],["Galvanisieren","elektrochemisches Abscheiden von Metallschichten (Zink, Chrom, Nickel)","Schrauben, Zierteile, Hartchrom"],["Thermisches Spritzen (Flammspritzen, Plasmaspritzen)","Spritzwerkstoff wird geschmolzen und auf das Bauteil geschleudert","Verschleißschutz, Wärmedämmschichten"],["PVD / CVD","dünne Hartstoffschichten aus der Gasphase (TiN, TiAlN, DLC)","Werkzeugbeschichtung, Reibungsminderung"],["Eloxieren","anodische Oxidation von Aluminium","Korrosionsschutz, Färben"]]},{"p":"Die Haftung der Schicht hängt von der Oberflächenvorbereitung ab: entfetten, beizen, strahlen. Rauheit, Sauberkeit und Temperatur entscheiden über Lebensdauer."},{"ul":["Korrosionsschutz: Barriere (Lack), kathodischer Schutz (Zink opfert sich), Passivierung (Chrom, Aluminiumoxid)","Verschleißschutz: Hartchrom, Nitrieren, Hartstoffschichten, Auftragsschweißen","Kontaktkorrosion: Bei Paarung edler und unedler Metalle in Gegenwart von Feuchtigkeit wird das unedlere zerstört"]},{"merke":"Beschichten gehört nach DIN 8580 zur Hauptgruppe 5. Plasmanitrieren oder Härten sind dagegen Stoffeigenschaft ändern (Hauptgruppe 6)."},{"falle":"Nitrieren erzeugt eine harte Randschicht im Werkstoff (Stoffeigenschaft ändern), kein Beschichten. Verzinken ist dagegen Beschichten."}]},
  {"t":"Toleranzen, Passungen und Oberflächenangaben","h":"Maßtoleranz, ISO-Passungen und Rauheit","b":[{"p":"Jede Fertigung hat Abweichungen. Toleranzen legen fest, wie viel ein Maß vom Nennmaß abweichen darf. Das Höchstmaß ist Nennmaß plus oberes Abmaß, das Mindestmaß Nennmaß plus unteres Abmaß."},{"fx":{"n":"Toleranz","tex":"T = G_o - G_u = ES - EI","leg":[["T","Toleranz in mm"],["G_o","Höchstmaß"],["G_u","Mindestmaß"],["ES, EI","oberes und unteres Abmaß (Bohrung); es, ei bei Wellen"]],"e":"Beispiel Ø 50 H7: oberes Abmaß +25 µm, unteres 0 → Höchstmaß 50,025 mm, Mindestmaß 50,000 mm, T = 25 µm."}},{"ul":["Passungssystem Einheitsbohrung: Bohrung H (unteres Abmaß 0), die Welle wird passend gewählt – üblich, weil Bohrungen mit festen Reibahlen hergestellt werden","Einheitswelle: Welle h (oberes Abmaß 0) – für gezogene Wellen, mehrere Bohrungen auf einer Welle","Spielpassung: immer Spiel (z. B. H7/f7); Übergangspassung: Spiel oder Übermaß (H7/k6); Presspassung: immer Übermaß (H7/s6)","Grundtoleranzgrade IT: Kleinere Zahl = kleinere Toleranz = höhere Fertigungskosten"]},{"fx":{"n":"Spiel und Übermaß","tex":"P_{S,max} = G_{oB} - G_{uW},\\quad P_{S,min} = G_{uB} - G_{oW}","leg":[["P_S","Spiel (negativ = Übermaß)"],["G_oB, G_uB","Höchst- und Mindestmaß der Bohrung"],["G_oW, G_uW","Höchst- und Mindestmaß der Welle"]],"e":"Größtspiel = Höchstmaß Bohrung − Mindestmaß Welle; Kleinstspiel = Mindestmaß Bohrung − Höchstmaß Welle. Beide positiv: Spielpassung; beide negativ: Presspassung; Vorzeichen wechselt: Übergangspassung."}},{"p":"Oberflächen werden durch Rauheitskennwerte beschrieben. Ra ist der arithmetische Mittenrauwert, Rz die gemittelte Rautiefe. Rz ist empfindlicher für einzelne Spitzen und Riefen. Schleifen erreicht etwa Ra 0,2–1,6 µm, Schlichtdrehen Ra 1,6–3,2 µm, Schruppen Ra 6,3–12,5 µm."},{"ul":["Allgemeintoleranzen ISO 2768 gelten, wenn keine Einzeltoleranz angegeben ist (Klassen f fein, m mittel, c grob, v sehr grob)","Form- und Lagetoleranzen (Ebenheit, Rundheit, Rechtwinkligkeit, Koaxialität) begrenzen Gestaltabweichungen unabhängig von Maßen","Unabhängigkeitsprinzip: Maß-, Form- und Lagetoleranzen gelten unabhängig voneinander, sofern nichts anderes angegeben (Hüllbedingung E)"]},{"falle":"Kleinstspiel und Größtspiel nicht verwechseln: Größtspiel = Höchstmaß Bohrung − Mindestmaß Welle. Bei Presspassungen sind beide Werte negativ, das Übermaß ist der Betrag."}]},
  {"t":"Arbeitsplan, Fertigungsplanung und Zeiten","h":"Vom Rohteil zum fertigen Werkstück","b":[{"p":"Der Arbeitsplan legt die Fertigungsschritte, Maschinen, Werkzeuge, Vorrichtungen und Zeiten für ein Teil fest. Er entsteht aus Zeichnung, Stückliste, Rohteil und verfügbaren Betriebsmitteln. Der Meister prüft ihn auf Durchführbarkeit, Wirtschaftlichkeit und Qualität."},{"ol":["Rohteil festlegen (Halbzeug, Guss, Schmiedeteil, Abmessung mit Bearbeitungszugabe)","Aufspannung und Bezugsflächen planen (erst Bezugsflächen, dann Funktionsflächen)","Arbeitsgänge ordnen: Schruppen vor Schlichten, Wärmebehandlung vor Fertigbearbeiten (Härteverzug), Schleifen zuletzt","Maschinen, Werkzeuge, Prüfmittel und Schnittwerte zuordnen","Zeiten ermitteln: Rüstzeit, Hauptnutzungszeit, Nebenzeiten","Prüfplan ergänzen (Prüfmerkmale, Prüfmittel, Häufigkeit)"]},{"fx":{"n":"Auftragszeit","tex":"t_a = t_r + m \\cdot t_e","leg":[["t_a","Auftragszeit in min"],["t_r","Rüstzeit je Auftrag in min"],["m","Menge"],["t_e","Ausführungszeit je Stück in min"]],"e":"Ausführungszeit je Stück: te = tg · (1 + Verteilzeitzuschlag), die Grundzeit tg setzt sich aus Haupt- und Nebenzeit zusammen."}},{"ul":["Hauptzeit th: Zeit, in der das Werkzeug zerspant und das Werkstück verändert wird","Nebenzeit tn: Spannen, Messen, Werkzeug wechseln, Anfahren","Verteilzeit tv: sachlich (Störungen) und persönlich (Erholung)","Rüstzeit tr: Vorbereiten der Maschine (Rüsten) und Aufräumen, einmal je Los","Losgröße: Große Lose verteilen die Rüstzeit auf mehr Teile (kleinere Stückkosten) binden aber Kapital und Lagerplatz"]},{"merke":"Wärmebehandlung vor dem Fertigschleifen planen: Das Härten verzieht Teile, deshalb bleibt Schleifaufmaß stehen und die Funktionsflächen werden am Ende geschliffen."},{"falle":"Die Rüstzeit fällt je Auftrag einmal an, die Ausführungszeit je Stück. Bei der Stückzeit nicht die gesamte Rüstzeit je Teil ansetzen, sondern auf die Losgröße verteilen."}]},
  {"t":"Werkstoffprüfung: Zugversuch, Härte, Kerbschlag","h":"Kennwerte ermitteln und deuten","b":[{"p":"Der Zugversuch (DIN EN ISO 6892) belastet eine Probe bis zum Bruch. Aus dem Spannungs-Dehnungs-Diagramm folgen Streckgrenze, Zugfestigkeit und Bruchdehnung. Ohne ausgeprägte Streckgrenze (z. B. vergüteter Stahl, Aluminium) gilt die 0,2-%-Dehngrenze Rp0,2."},{"fx":{"n":"Spannung und Dehnung","tex":"\\sigma = \\frac{F}{S_0},\\quad \\varepsilon = \\frac{\\Delta L}{L_0},\\quad A = \\frac{L_u - L_0}{L_0} \\cdot 100\\ \\%","leg":[["σ","Spannung in N/mm²"],["F","Zugkraft in N"],["S_0","Ursprungsquerschnitt in mm²"],["A","Bruchdehnung in %"],["L_0, L_u","Anfangs- und Endmesslänge"]],"e":"R_m = F_max : S_0 (Zugfestigkeit), R_e = F_e : S_0 (Streckgrenze). Im elastischen Bereich gilt das Hookesche Gesetz σ = E · ε."}},{"tab":[["Härteprüfung","Prinzip","Einsatz"],["Brinell (HBW)","Hartmetallkugel, Eindruckdurchmesser wird gemessen","weiche bis mittelharte Werkstoffe, Guss, Rohteile; Rm ≈ 3,5 · HB für Stahl"],["Vickers (HV)","Diamantpyramide, Eindruckdiagonalen werden gemessen","alle Werkstoffe, dünne Schichten, Randhärte, Härteverlauf"],["Rockwell (HRC, HRB)","Eindringtiefe unter Vorlast und Prüflast, Anzeige direkt","gehärteter Stahl (HRC), schnelle Serienprüfung"]]},{"p":"Der Kerbschlagbiegeversuch (Charpy) misst die beim Durchschlagen einer gekerbten Probe verbrauchte Schlagarbeit und beurteilt die Zähigkeit. Bei tiefen Temperaturen sinkt die Kerbschlagarbeit stark (Steilabfall, Sprödbruch)."},{"ul":["Dauerschwingversuch (Wöhler): Ermittelt die Dauerfestigkeit bei schwingender Belastung; Kerben und raue Oberflächen senken sie","Zerstörungsfreie Prüfung: Sichtprüfung, Eindringprüfung (Risse an der Oberfläche), Magnetpulverprüfung (ferromagnetisch, Oberflächennähe), Ultraschall (innere Fehler), Durchstrahlung (Röntgen), Wirbelstromprüfung","Härteprüfung ist nahezu zerstörungsfrei und gibt einen schnellen Hinweis auf Festigkeit und Wärmebehandlung"]},{"merke":"Streckgrenze = Beginn bleibender Verformung; Zugfestigkeit = höchste Spannung; Bruchdehnung beschreibt die Zähigkeit (Verformbarkeit). Zäher Werkstoff: große Bruchdehnung und große Kerbschlagarbeit."},{"falle":"Spannung wird auf den Ursprungsquerschnitt S₀ bezogen, nicht auf den eingeschnürten Querschnitt. Brinell eignet sich nicht für sehr harte Werkstoffe (Kugel verformt sich), dort Vickers oder Rockwell C."}]},
  {"t":"Kunststoffe und ihre Verarbeitung","h":"Thermoplaste, Duroplaste, Elastomere und Formgebung","b":[{"tab":[["Gruppe","Aufbau","Verhalten","Beispiele"],["Thermoplaste","lineare oder verzweigte Makromoleküle, nicht vernetzt","in der Wärme erweichbar und wiederholt schmelzbar, schweißbar","PE, PP, PVC, PA, POM, PET, PC"],["Duroplaste","engmaschig vernetzt","nach dem Aushärten nicht mehr schmelzbar oder umformbar, hart, spröde","Phenolharz (PF), Epoxidharz (EP), UP-Harz"],["Elastomere","weitmaschig vernetzt","gummielastisch, bei Belastung verformbar, kehren zurück","Gummi, Silikon, Polyurethan-Elastomer"]]},{"tab":[["Verfahren","Prinzip","Teile"],["Spritzgießen","Granulat wird aufgeschmolzen und unter Druck in ein gekühltes Werkzeug gespritzt","Serien, komplexe Teile, hohe Stückzahl"],["Extrudieren","Schnecke presst die Schmelze durch eine Düse (Profil)","Rohre, Profile, Folien"],["Blasformen","Schmelzeschlauch wird in der Form aufgeblasen","Flaschen, Behälter"],["Tiefziehen (Thermoformen)","erwärmte Platte wird in die Form gezogen","Verpackungen, Verkleidungen"],["Pressen / Spritzpressen","Duroplast wird in der heißen Form ausgehärtet","Isolierteile, Schalter"]]},{"ul":["Einflussgrößen beim Spritzgießen: Massetemperatur, Werkzeugtemperatur, Einspritzdruck, Nachdruck, Kühlzeit; Fehler sind Einfallstellen, Lunker, Verzug, Gratbildung, Bindenähte","Schwindung: Kunststoffe schrumpfen beim Abkühlen, das Werkzeug muss entsprechend größer sein","Kriechen: Unter Dauerlast verformen sich Kunststoffe langsam – bei Konstruktion beachten","Feuchte: PA nimmt Wasser auf (Maßänderung, Festigkeit), Granulat vor der Verarbeitung trocknen","Recycling: sortenrein trennen; Thermoplaste lassen sich einschmelzen, Duroplaste nur stofflich oder energetisch verwerten"]},{"merke":"Thermoplast: erwärmen – formen – abkühlen, wiederholbar. Duroplast: formen und gleichzeitig aushärten, nicht wiederholbar."},{"falle":"Spritzgießen ist Urformen (Hauptgruppe 1), Tiefziehen von Thermoplasten dagegen Umformen (Hauptgruppe 2). Schweißen von Kunststoffen gelingt nur bei Thermoplasten."}]},
  {"t":"Fertigungsprinzipien und Fertigungsarten","h":"Wie ist die Fertigung organisiert?","b":[{"tab":[["Prinzip","Merkmale","Vorteile","Nachteile"],["Werkstattfertigung (Verrichtungsprinzip)","gleiche Maschinen räumlich zusammengefasst (Dreherei, Fräserei)","flexibel, geeignet für Einzel- und Kleinserien, Ausfall einer Maschine wird ausgeglichen","lange Transportwege und Durchlaufzeiten, viele Zwischenlager, hohe Bestände"],["Fließfertigung (Flussprinzip)","Maschinen in der Reihenfolge der Arbeitsgänge angeordnet, getaktet","kurze Durchlaufzeiten, geringe Bestände, einfache Steuerung","unflexibel, Ausfall legt die Linie lahm, hohe Investition"],["Gruppenfertigung / Fertigungsinsel","Teilefamilie wird komplett in einer Gruppe (Zelle) gefertigt","kurze Wege, Teamverantwortung, gute Qualitätsverantwortung","Mitarbeiter müssen mehrere Maschinen beherrschen"],["Baustellenfertigung","Produkt bleibt am Ort, Betriebsmittel kommen zum Produkt","große, nicht transportierbare Produkte (Schiff, Brücke, Windrad)","aufwendige Logistik, wechselnde Bedingungen"]]},{"tab":[["Fertigungsart","Stückzahl","Typisch"],["Einzelfertigung","1 Stück","Sondermaschinen, Prototypen"],["Serienfertigung","begrenzte Auflagen, Wiederholung","Werkzeugmaschinen, Getriebe"],["Sortenfertigung","ähnliche Produkte aus gleichem Grundstoff","Walzwerke, Brauerei"],["Massenfertigung","sehr große Stückzahlen, lange Zeit","Schrauben, Lager, Automobilteile"]]},{"ul":["Flexible Fertigungssysteme (FFS) verbinden CNC-Maschinen, automatischen Transport (FTS) und Werkzeugwechsel zu einem flexibel nutzbaren Verbund","Taktzeit: Die langsamste Station bestimmt den Takt in der Fließfertigung (Engpass)","Fertigungsinseln erhöhen Verantwortung und Qualität, verkürzen Durchlaufzeit und senken Bestände"]},{"merke":"Je größer die Stückzahl und je standardisierter das Produkt, desto eher lohnt Fließfertigung. Je größer die Produktvielfalt und je kleiner die Auflage, desto eher Werkstatt- oder Inselfertigung."},{"falle":"Das Verrichtungsprinzip fasst gleiche Tätigkeiten zusammen (Werkstatt), das Flussprinzip richtet sich nach dem Materialfluss (Fließfertigung). Nicht verwechseln."}]},
 {"t":"Schneidkeil, Winkel und Schneidengeometrie","h":"Frei-, Keil- und Spanwinkel, Einstellwinkel, Eckenradius","b":[{"p":"Jede Schneide zerspant mit einem Keil. Seine Winkel entscheiden über Schnittkraft, Spanablauf, Verschleiß und Oberfläche. Die Winkel werden an der Werkzeugschneide in der Werkzeug-Orthogonalebene gemessen und ergeben zusammen immer 90°."},{"fx":{"n":"Winkelsumme am Schneidkeil","tex":"\\alpha + \\beta + \\gamma = 90^\\circ","leg":[["\\alpha","Freiwinkel: zwischen Freifläche und Schnittfläche, verhindert Reibung der Freifläche am Werkstück"],["\\beta","Keilwinkel: zwischen Freifläche und Spanfläche, bestimmt die Stabilität der Schneide"],["\\gamma","Spanwinkel: zwischen Spanfläche und Senkrechter zur Schnittfläche, bestimmt den Spanablauf"]],"e":"Wird γ größer, wird β kleiner – die Schneide schneidet leichter, ist aber weniger stabil."}},{"svg":{"w":520,"h":230,"cap":"Schneidkeil im Schnitt: α + β + γ = 90°","body":"<polygon points=\"150,170 380,170 150,50\" class=\"sk-body\"/><line x1=\"40\" y1=\"170\" x2=\"470\" y2=\"170\" class=\"sk-c\"/><line x1=\"150\" y1=\"30\" x2=\"150\" y2=\"200\" class=\"sk-c\"/><text x=\"198\" y=\"158\" class=\"sk-t\">β</text><text x=\"95\" y=\"130\" class=\"sk-t\">α</text><text x=\"165\" y=\"110\" class=\"sk-t\">γ</text><text x=\"395\" y=\"165\" class=\"sk-t\">Spanfläche</text><text x=\"40\" y=\"195\" class=\"sk-t\">Freifläche</text><text x=\"40\" y=\"162\" class=\"sk-t\">Schnittfläche</text>"}},{"tab":[["Werkstoff / Schneidstoff","Spanwinkel γ","Folge"],["weiche Werkstoffe (Aluminium, Kupfer)","groß, bis 20° und mehr","leichter Schnitt, geringe Kraft; Schneide empfindlicher"],["Stahl mit Hartmetall","mittel, etwa 0° bis 12°","Kompromiss aus Standzeit und Schnittkraft"],["harte, spröde Werkstoffe, gehärteter Stahl","klein bis negativ","stabile Schneide, hohe Schnittkräfte, steife Maschine nötig"],["Wendeschneidplatten (negativ)","γ negativ, Platte „liegt“ im Halter","beidseitig nutzbar (mehr Schneiden), robust"]]},{"h":"Winkel in der Draufsicht"},{"ul":["Einstellwinkel κ: Winkel zwischen Hauptschneide und Vorschubrichtung. Er verteilt die Kraft auf Schnitttiefe und Vorschub: Spanungsdicke h = f · sin κ, Spanungsbreite b = a_p / sin κ.","Eckenwinkel ε: Winkel zwischen Haupt- und Nebenschneide; große ε = stabile Schneidenecke.","Neigungswinkel λ: lenkt den Span zur Seite; beim Drehen etwa −6° bis +6°.","Eckenradius r: ein großer Radius ergibt bessere Oberfläche und stabilere Ecke, erhöht aber die Passivkraft (Rattern bei dünnen Wellen)."]},{"fx":{"n":"Theoretische Rautiefe","tex":"R_{th} = \\frac{f^{2}}{8 \\cdot r_\\varepsilon} \\cdot 1000","leg":[["R_{th}","theoretische Rautiefe in µm"],["f","Vorschub in mm"],["r_\\varepsilon","Eckenradius in mm"]],"e":"Verdoppelt man den Vorschub, steigt die Rautiefe auf das Vierfache; ein doppelt so großer Radius halbiert sie."}},{"bsp":{"t":"Beispiel","b":["f = 0,2 mm, r = 0,8 mm","R_th = 0,2² / (8 · 0,8) · 1000 = 0,04 / 6,4 · 1000 = 6,25 µm","Soll Rz höchstens 4 µm betragen: f ≤ √(8 · r · Rz / 1000) = √(8 · 0,8 · 4 / 1000) = 0,16 mm"]}},{"merke":"Spanwinkel groß = leichter Schnitt, Keilwinkel groß = stabile Schneide. Beides gleichzeitig geht nicht, weil α + β + γ = 90° gilt."},{"falle":"Rauheit mit Vorschub und Eckenradius steuern, nicht mit der Schnittgeschwindigkeit allein. Zu kleine vc führt zusätzlich zur Aufbauschneide und verschlechtert die Oberfläche."}]},
 {"t":"Spannen und Bestimmen von Werkstücken: 3-2-1-Regel und Spannmittel","h":"Freiheitsgrade, Auflagepunkte, Spannkraft","b":[{"p":"Ein frei im Raum liegendes Werkstück hat sechs Freiheitsgrade: je drei Verschiebungen und Drehungen. Beim Bestimmen werden sie durch Auflagepunkte genommen, das Spannen hält das Werkstück in dieser Lage. Bestimmen und Spannen sind zwei getrennte Aufgaben."},{"svg":{"w":520,"h":240,"cap":"3-2-1-Regel: drei Punkte Hauptauflage, zwei Punkte Führung, ein Punkt Anschlag","body":"<polygon points=\"140,170 360,170 400,130 180,130\" class=\"sk-body\"/><polygon points=\"140,170 360,170 360,200 140,200\" class=\"sk-body\"/><circle cx=\"170\" cy=\"185\" r=\"6\" class=\"sk-f\"/><circle cx=\"330\" cy=\"185\" r=\"6\" class=\"sk-f\"/><circle cx=\"250\" cy=\"150\" r=\"0.1\" class=\"sk-f\"/><text x=\"150\" y=\"222\" class=\"sk-t\">3 Punkte (Hauptauflage)</text><circle cx=\"205\" cy=\"150\" r=\"5\" class=\"sk-f\"/><circle cx=\"305\" cy=\"150\" r=\"5\" class=\"sk-f\"/><text x=\"420\" y=\"150\" class=\"sk-t\">2 Punkte (Führung)</text><circle cx=\"372\" cy=\"150\" r=\"5\" class=\"sk-f\"/><text x=\"388\" y=\"110\" class=\"sk-t\">1 Punkt (Anschlag)</text>"}},{"tab":[["Auflage","Punkte","Genommene Freiheitsgrade"],["Hauptauflage (größte Fläche)","3","1 Verschiebung + 2 Drehungen"],["Führungsfläche (lange Kante)","2","1 Verschiebung + 1 Drehung"],["Anschlag (kurze Kante)","1","1 Verschiebung"],["Summe","6","alle sechs Freiheitsgrade"]]},{"merke":"Mehr als sechs Auflagepunkte = Überbestimmung. Das Werkstück liegt dann nicht definiert, verzieht sich beim Spannen und wird ungenau. Rohe Gussflächen nur auf wenigen, einstellbaren Punkten auflegen."},{"h":"Spannmittel im Überblick"},{"tab":[["Spannmittel","Einsatz","Merkmal"],["Maschinenschraubstock","prismatische Teile auf Fräsmaschinen","schnell, Spannbacken ersetzbar; Teil nicht über Backen hinaus durchbiegen"],["Dreibackenfutter","runde Teile beim Drehen","zentrisch spannend, schnell, Rundlauf wenige Hundertstel"],["Vierbackenfutter","unrunde oder exzentrische Teile","jede Backe einzeln einstellbar, genauer, langsamer"],["Spannzange","kleine runde Teile, hohe Genauigkeit","Rundlauf besser 0,01 mm, geringer Spannbereich"],["Spannpratzen auf Aufspanntisch","große, sperrige Teile","Pratze nahe an der Auflage, Schraube nahe am Werkstück"],["Magnet- und Vakuumspanntisch","dünne Platten, ferromagnetisch bzw. dichte Flächen","verzugsarm, frei zugängliche Seiten, begrenzte Haltekraft"],["Nullpunktspannsystem","Palettenwechsel, Serien","wiederholgenau, kurze Rüstzeit"]]},{"fx":{"n":"Erforderliche Spannkraft bei Reibschluss","tex":"F_{sp} = \\frac{S \\cdot F_c}{\\mu \\cdot n}","leg":[["F_{sp}","Spannkraft je Spannstelle in N"],["S","Sicherheitsfaktor, meist 1,5 bis 3"],["F_c","Schnittkraft in N"],["\\mu","Reibungszahl zwischen Backe und Werkstück"],["n","Anzahl der Reibflächen"]],"e":"Die Reibung muss die Schnittkraft sicher übertragen. Geriffelte Backen erhöhen μ, hinterlassen aber Spuren."}},{"bsp":{"t":"Beispiel","b":["F_c = 1.800 N, S = 2, μ = 0,15, 2 Reibflächen","F_sp = 2 · 1.800 / (0,15 · 2) = 12.000 N"]}},{"falle":"Spannen verformt das Werkstück: Eine dünnwandige Hülse wird im Dreibackenfutter unrund (Dreieck) gespannt und nach dem Lösen unrund. Abhilfe: weiche Backen, Spannhülsen, mehr Spannstellen, geringere Spannkraft, Schlichten im gelösten Zustand."}]},
 {"t":"Gewinde herstellen: Schneiden, Formen, Fräsen, Drehen","h":"Kernloch, Gewindeprofil, Verfahren und Auswahl","b":[{"p":"Metrische ISO-Gewinde (M) sind mit Nenndurchmesser d und Steigung P festgelegt. Regelgewinde gibt nur d an (M10), Feingewinde auch die Steigung (M10 × 1). Die Toleranz steht dahinter, z. B. 6H für das Muttergewinde und 6g für das Bolzengewinde."},{"fx":{"n":"Kerndurchmesser und Kernloch","tex":"D_1 = d - 1{,}0825 \\cdot P \\qquad d_3 = d - 1{,}2269 \\cdot P \\qquad d_{Kernloch} \\approx d - P","leg":[["d","Nenndurchmesser in mm"],["P","Steigung in mm"],["D_1","Kerndurchmesser Muttergewinde"],["d_3","Kerndurchmesser Bolzengewinde"],["d_{Kernloch}","Bohrerdurchmesser fürs Gewindeschneiden"]],"e":"Kernloch für Gewindeschneiden: d − P (M10: 10 − 1,5 = 8,5 mm). Beim Gewindeformen wird der Werkstoff verdrängt, dafür ist das Kernloch etwas größer (etwa d − 0,5 · P)."}},{"fx":{"n":"Spannungsquerschnitt","tex":"A_s = \\frac{\\pi}{4} \\cdot \\left(\\frac{d_2 + d_3}{2}\\right)^{2}","leg":[["A_s","Spannungsquerschnitt in mm² (aus dem Tabellenbuch)"],["d_2","Flankendurchmesser"],["d_3","Kerndurchmesser"]],"e":"Für Festigkeitsrechnungen am Gewinde nimmt man As aus der Tabelle, nicht den Nenndurchmesser."}},{"tab":[["Gewinde","P in mm","Kernloch (d − P)","As in mm²"],["M8","1,25","6,75 mm","36,6"],["M10","1,5","8,5 mm","58,0"],["M12","1,75","10,25 mm","84,3"],["M16","2","14 mm","157"],["M20","2,5","17,5 mm","245"],["M24","3","21 mm","353"]]},{"h":"Verfahren"},{"tab":[["Verfahren","Prinzip","Vorteile","Grenzen"],["Gewindeschneiden mit Gewindebohrer","spanend, Vor-, Mittel- und Fertigschneider","einfach, Handgewinde und Maschine","Bruchgefahr, Späne im Sackloch"],["Gewindefurchen / -formen","spanlos, Werkstoff wird verdrängt","keine Späne, höhere Festigkeit durch Faserverlauf, lange Standzeit","nur duktile Werkstoffe, Schmierung nötig"],["Gewindefräsen","CNC, Kreisbahn mit Schraubenlinie","ein Werkzeug für mehrere Durchmesser, Sacklöcher bis zum Grund, wenig Bruchrisiko","CNC-Maschine, etwas höhere Zeit"],["Gewindedrehen","Gewindedrehmeißel, mehrere Zustellungen","Außen- und Innengewinde, Sondergewinde, Trapez","Maschine mit Spindelsynchronisation"],["Gewindewalzen","spanlos mit Rollen, Außengewinde","Großserie, Oberfläche glatt, hohe Dauerfestigkeit","Rohling-Durchmesser etwa Flankendurchmesser"]]},{"ul":["Durchgangsloch: Gewindebohrer mit Schälanschnitt (gerade genutet) – die Späne werden nach vorn ausgeschoben.","Sackloch: Gewindebohrer mit Spiralnut – die Späne werden nach hinten herausgefördert.","Maschinen-Gewindebohrer mit Ausgleichsfutter oder synchronem Gewindebohren vermeiden Bruch."]},{"falle":"Das Kernloch ist kein Wahlwert. Zu klein: Gewindebohrer bricht, zu groß: nicht volle Gewindetiefe, geringere Tragfähigkeit. Die Gewindetiefe im Sackloch plus Überlauf des Bohrers einplanen."}]},
 {"t":"Rauheit: Kenngrößen, Messung und erreichbare Werte","h":"Ra, Rz, Rmax, Tastschnittverfahren und Verfahrensvergleich","b":[{"p":"Die Rauheit beschreibt die feinen Unebenheiten der Oberfläche und wird im Tastschnitt mit einer Diamantspitze gemessen. Sie beeinflusst Reibung, Verschleiß, Dichtwirkung, Schwingfestigkeit und Haftung von Beschichtungen."},{"tab":[["Kenngröße","Bedeutung","Hinweis"],["Ra","arithmetischer Mittenrauwert: Mittelwert der Abweichungen vom Mittellinienprofil","unempfindlich gegen Einzelspitzen, in der Praxis häufigste Angabe"],["Rz","gemittelte Rautiefe: Mittelwert aus fünf Einzelmessstrecken","erfasst Spitzen und Riefen, typischer Zeichnungswert für Dichtflächen"],["Rmax","größte Einzelrautiefe auf der Gesamtmessstrecke","wird bei Sicherheitsteilen und Dichtflächen gefordert"],["Rmr (Traganteil)","Materialanteil in einer Schnitthöhe","Gleit- und Dichtflächen"]]},{"fx":{"n":"Faustbeziehung","tex":"R_z \\approx 4 \\ldots 7 \\cdot R_a","leg":[["R_z","gemittelte Rautiefe in µm"],["R_a","Mittenrauwert in µm"]],"e":"Nur eine grobe Umrechnung! Rauheit muss an der Zeichnung in dem Wert gemessen werden, der dort steht."}},{"h":"Erreichbare Rauheit (Richtwerte)"},{"tab":[["Verfahren","typischer Bereich Ra in µm","Beispiel"],["Schruppdrehen / -fräsen","6,3 bis 25","Rohmaß, Freiflächen"],["Schlichtdrehen / -fräsen","1,6 bis 3,2","Passflächen allgemein"],["Feindrehen, Diamantfräsen","0,2 bis 0,8","Hydraulik-, Dichtflächen"],["Rundschleifen","0,2 bis 1,6","Lagersitze"],["Honen","0,05 bis 0,4","Zylinderlaufbahnen"],["Läppen, Polieren","0,01 bis 0,1","Messmittel, Ventilsitze"]]},{"ul":["Messstrecke nach Norm: Gesamtmessstrecke = fünf Einzelmessstrecken; die Einzelmessstrecke entspricht der Grenzwellenlänge λc (z. B. 0,8 mm bei Ra 0,1 bis 2 µm).","Messrichtung quer zur Bearbeitungsrichtung (Rillen).","Handrauheitsmessgeräte arbeiten mit Tastspitze, Vergleichsmuster eignen sich für den Schnellvergleich in der Werkstatt."]},{"bsp":{"t":"Zeichnungseintrag","b":["Rz 6,3: Die gemittelte Rautiefe darf 6,3 µm nicht überschreiten.","Mit Strich im Zeichen (√ mit Querstrich): Oberfläche wird spanend hergestellt.","Aufpassen: feinere Rauheit verlangt aufwendigere Verfahren und damit höhere Kosten. Nie feiner fordern als funktional nötig."]}},{"falle":"Rauheit nicht mit Toleranz verwechseln: Eine Passfläche mit IT6 braucht etwa Ra 0,8, aber eine Ra-0,8-Fläche ist nicht automatisch maßhaltig. Maß-/Formtoleranz und Rauheit sind getrennte Anforderungen."}]},
 {"t":"Fertigungsmesstechnik: Messmittel, Temperatur und Koordinatenmessgerät","h":"Messschieber, Bügelmessschraube, Lehren, Temperatureinfluss, 3D-Messung","b":[{"p":"In der Fertigung entscheidet das Messmittel, ob ein Teil gut oder schlecht ist. Wichtig sind Auflösung, Fehlergrenze, Handhabung und Umgebung. Das Messmittel muss zur Toleranz passen: Faustregel Messunsicherheit höchstens ein Zehntel der Toleranz."},{"tab":[["Messmittel","Ablesung / Auflösung","Einsatz"],["Messschieber","0,05 mm oder 0,02 mm, digital 0,01 mm","Außen-, Innen-, Tiefenmaße, allgemeine Maße"],["Bügelmessschraube","0,01 mm","genauere Außenmaße, Wellendurchmesser"],["Messuhr / Feinzeiger","0,01 mm bzw. 0,001 mm","Rund- und Planlauf, Vergleichsmessen"],["Grenzrachenlehre, Grenzlehrdorn","Gut-/Ausschuss-Aussage","Serie, schnelle Prüfung von Passungen"],["Höhenmessgerät, Messtisch","0,01 mm","Anreißen und Messen von Höhen"],["Koordinatenmessgerät (KMG)","Auflösung bis 0,001 mm","3D-Form, Lage, komplexe Teile"]]},{"h":"Temperatur"},{"p":"Alle Maße gelten bei 20 °C. Warme Teile aus der Zerspanung messen daher falsch. Teile und Messmittel müssen sich der Raumtemperatur angleichen."},{"fx":{"n":"Längenänderung durch Temperatur","tex":"\\Delta L = \\alpha \\cdot L \\cdot \\Delta \\vartheta","leg":[["\\Delta L","Längenänderung in mm"],["\\alpha","Längenausdehnungskoeffizient in 1/K (Stahl 11,5 · 10⁻⁶, Aluminium 23,8 · 10⁻⁶)"],["L","Ausgangslänge in mm"],["\\Delta \\vartheta","Temperaturdifferenz in K"]]}},{"bsp":{"t":"Beispiel","b":["Stahlwelle 500 mm lang, 10 K wärmer als 20 °C","ΔL = 11,5 · 10⁻⁶ · 500 · 10 = 0,0575 mm","Bei Toleranz 0,05 mm wäre das Messergebnis wertlos. Erst abkühlen lassen."]}},{"h":"Koordinatenmessgerät (KMG)"},{"ul":["Ein Messkopf tastet Punkte auf der Oberfläche an; aus den Koordinaten werden Maße, Formen (Kreis, Ebene) und Lagen (Abstand, Parallelität, Position) berechnet.","Bauformen: Portal, Ständer, Brücke; Messkopf schaltend oder messend (scannend); optisch bei weichen oder kleinen Teilen.","Messprogramm aus CAD-Modell, Teile auf Vorrichtung ausrichten (Ausrichten = Koordinatensystem festlegen), Messprotokoll mit Soll-, Istwert und Abweichung.","Vorteile: ein Messmittel für viele Merkmale, dokumentierte Ergebnisse, Messen in der Serie ohne Bedienereinfluss.","Grenzen: Messraum klimatisiert, Messzeit, Tasterradius-Korrektur und Antastrichtung beeinflussen das Ergebnis."]},{"merke":"Abbe-Prinzip: Messstrecke und Maßstab sollen auf einer Linie liegen. Der Messschieber verletzt dieses Prinzip (Kippfehler), die Bügelmessschraube hält es ein."},{"falle":"Das Messmittel selbst kann falsch sein: Prüfmittel regelmäßig kalibrieren und im Prüfmittelverzeichnis führen. Ein unkalibriertes Prüfmittel ist nach ISO 9001 keine Nachweisgrundlage."}]},
 {"t":"Schweißnähte: Kennwerte, Nahtberechnung und Schweißverzug","h":"Kehlnaht, Stumpfnaht, Bewertungsgruppen, Vorwärmen, Verzug","b":[{"p":"Schweißnähte werden nach Form, Lage und Beanspruchung ausgelegt. Für die Festigkeitsrechnung zählt die tragende Nahtfläche, nicht die Nahtlänge allein."},{"tab":[["Naht","Skizze der Idee","Rechengröße"],["Stumpfnaht (I-, V-, X-Naht)","Bleche im Stoß verbunden","Fläche = Blechdicke s · Nahtlänge l"],["Kehlnaht","Dreiecknaht in Ecke oder Überlappung","Nahtdicke a = Höhe des einschreibbaren Dreiecks, Fläche = a · l"]]},{"fx":{"n":"Nahtspannung bei Kehlnähten","tex":"\\sigma_w = \\frac{F}{n \\cdot a \\cdot l_w} \\le \\sigma_{w,zul}","leg":[["F","Betriebskraft in N"],["n","Anzahl der Nähte"],["a","Nahtdicke in mm"],["l_w","wirksame Nahtlänge in mm"],["\\sigma_{w,zul}","zulässige Nahtspannung in N/mm²"]],"e":"Zulässige Spannung = Streckgrenze des Grundwerkstoffs : Sicherheitszahl. Die Nahtlänge wird um Endkrater verkürzt, wenn nicht rundum geschweißt wird."}},{"bsp":{"t":"Beispiel","b":["Flachstahl 60 mm breit, beidseitig Kehlnaht a = 4 mm, 90 % der Breite tragend, S235, ν = 1,5","l = 0,9 · 60 = 54 mm; σ_zul = 235 / 1,5 = 156,7 N/mm²","F = 156,7 · 4 · 2 · 54 = 67.700 N"]}},{"h":"Qualität und Prüfung"},{"ul":["Bewertungsgruppen nach DIN EN ISO 5817: B (höchste Anforderung), C, D (niedrigste). Je höher die Gruppe, desto strenger die zulässigen Unregelmäßigkeiten.","Schweißpositionen nach ISO 6947: PA Wannenlage, PB horizontale Kehlnaht, PC Querposition, PD Überkopf-Kehlnaht, PE Überkopf, PF steigend, PG fallend.","Schweißanweisung (WPS) legt Verfahren, Zusatz, Strom, Vorwärmen fest; Schweißer sind nach ISO 9606 geprüft; die Schweißaufsicht trägt die Verantwortung (ISO 14731).","Zerstörungsfreie Prüfung: Sichtprüfung (VT), Eindring- (PT), Magnetpulver- (MT), Durchstrahlungs- (RT) und Ultraschallprüfung (UT)."]},{"h":"Vorwärmen und Verzug"},{"fx":{"n":"Kohlenstoffäquivalent","tex":"CE = C + \\frac{Mn}{6} + \\frac{Cr + Mo + V}{5} + \\frac{Ni + Cu}{15}","leg":[["CE","Kohlenstoffäquivalent in %"],["C, Mn, Cr, Mo, V, Ni, Cu","Gehalte in Massenprozent"]],"e":"Je höher CE, desto härter wird die Wärmeeinflusszone und desto eher entstehen Risse. Ab etwa CE 0,45 % sollte vorgewärmt werden."}},{"ul":["Schrumpfung beim Abkühlen verzieht und spannt das Bauteil. Maßnahmen: wenig Nahtvolumen (kleines a-Maß, richtige Nahtform), symmetrisch und im Pilgerschritt schweißen, Heften, Vorrichtung, Wärmearm schweißen, Zugabe bei Maßteilen, Richten, Spannungsarmglühen.","Bei Kehlnähten: Nur so dick schweißen wie rechnerisch nötig, doppelte Nahtdicke vervierfacht das Nahtvolumen."]},{"falle":"a-Maß und z-Maß nicht verwechseln: a ist die Höhe des Dreiecks (Rechenwert), z die Schenkellänge. Es gilt a ≈ 0,7 · z."}]}
]};
